INSERT INTO `faq` (`id`, `pertanyaan`, `jawaban`, `updated_at`, `created_at`) VALUES
(1, 'Kenapa Senyum ?', 'Mudah digunakan, cepat dan dapat diakses dimana saja dan kapan saja (fleksibel). ', NULL, NULL),
(2, 'Aplikasi yang digunakan selain WhatsApp ?', 'Untuk saat ini, aplikasi yang kami gunakan adalah menggunakan Whatsapp dan tidak bisa menggunakan aplikasi chat (obrolan) yang lain.', NULL, NULL),
(3, 'Saya masih belum bisa menggunakan Aplikasi Senyum, apa yang harus saya lakukan ?', 'Pastikan Anda sudah memasang aplikasi WhatsApp di telepon genggam Anda. Pastikan nomor WA Aplikasi Senyum (0816764350) sudah disimpan pada telepon genggam Anda. Untuk memulai layanan, klik ikon Chat (obrolan) pada aplikasi WhatsApp anda. Ketik keyword (kata kunci) -SENYUM-. Aplikasi Senyum siap digunakan. ', NULL, NULL);
