INSERT INTO `pelayanan_publik` (`id`, `uid`, `kode`, `keyword`, `keterangan`, `response`, `file`, `mimes`, `id_opd`, `updated_at`, `created_at`) VALUES
(1, '5f949ec0-d035-4e2d-a395-1701a9ab5230', 'P001', 'INFORMASI LAYANAN PUBLIK', '', '<p>Prosedur permohonan informasi di PPID Utama :</p>', NULL, NULL, 30, NULL, NULL),
(3, '46755619-6b9b-4401-a73a-35886c598dcb', 'P002', 'TDG', 'TDG', '<p><strong>Tanda Daftar Gudang</strong></p>\r\n<p><strong>Persyaratan Administrasi :</strong></p>\r\n<ol>\r\n    <li>Fotocopi Akta Pendirian Perseroan Terbatas dan Pengesahan badan hukum dari pejabat yang berwenang dan akta perubahannya (jika ada), bagi pemilik gudang badan usaha berbentuk Perseroan Terbatas</li>\r\n    <li>Fotocopi Kartu Tanda Penduduk (KTP) Penanggungjawab Perusahaan</li>\r\n    <li>Izin Prinsip Penanaman Modal untuk Gudang bagi Perusahaan penanaman modal asing</li>\r\n    <li>Fotocopi Izin Mendirikan Bangunan (IMB) yang menyatakan sebagai Gudang</li>\r\n    <li>Fotocopi Surat Izin Gangguan (SIG)/HO</li>\r\n    <li>Pas Photo ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n    <li>Surat Kuasa (bila pengurusan perizinan diwakilkan).</li>\r\n</ol>\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-13 06:46:20', NULL),
(4, '83fb35d0-8d09-4599-87b3-93f9b0098ca4', 'P003', 'SIUP', 'SIUP', '<p><strong>IUP (SIUP : Surat Izin Usaha Perdagangan)</strong></p>\r\n\r\n<p><strong>Persyaratan Administrasi :</strong></p>\r\n\r\n<ol>\r\n	<li>Fotocopi Akta Notaris Pendirian Perusahaan</li>\r\n	<li>Fotocopi Akta Perubahan Perusahaan (apabila ada)</li>\r\n	<li>Fotocopi Surat Keputusan Pengesahaan Badan Hukum Perseroan Terbatas dari Departemen Hukum dan Hak Asasi Manusia</li>\r\n	<li>Fotocopi Kartu Tanda Penduduk (KTP) Penanggungjawab Perusahaan</li>\r\n	<li>Neraca Perusahaan</li>\r\n	<li>Fotocopi Pelunasan PBB tahun terakhir</li>\r\n	<li>Pas Photo ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n	<li>Surat Kuasa (bila pengurusan perizinan diwakilkan).</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-13 06:42:26', NULL),
(5, 'eb9fcbe8-c66e-4cd3-ba06-07f16030c9f9', 'P004', 'IUI', 'IUI', '<p style=\"text-align:justify\"><strong>IUI (Izin Usaha Industri)</strong></p>\r\n\r\n<p style=\"text-align:justify\"><strong>Persyaratan Administrasi :</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Fotocopi Akta Pendirian Perseroan Terbatas dan Pengesahan badan hukum dari pejabat yang berwenang dan akta perubahannya (jika ada), bagi pemilik gudang badan usaha berbentuk Perseroan Terbatas.</li>\r\n	<li style=\"text-align: justify;\">Fotocopi Kartu Tanda Penduduk (KTP) Penanggungjawab Perusahaan.</li>\r\n	<li style=\"text-align: justify;\">Izin Lokasi sesuai dengan peraturan yang berlaku.</li>\r\n	<li style=\"text-align: justify;\">Fotocopi Izin Mendirikan Bangunan (IMB).</li>\r\n	<li style=\"text-align: justify;\">Fotocopi Surat Izin Gangguan (SIG)/HO.</li>\r\n	<li style=\"text-align: justify;\">Fotocopi Dokumen Lingkungan.</li>\r\n	<li style=\"text-align: justify;\">Dokumen yang dipersyaratkan berdasarkan peraturan perundang-undangan bagi industri tertentu.</li>\r\n	<li style=\"text-align: justify;\">Pas Photo ukuran 3x4 cm sebanyak 4 (empat) lembar.</li>\r\n	<li style=\"text-align: justify;\">Surat Kuasa (bila pengurusan perizinan diwakilkan).</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:42:34', NULL),
(6, '147cb745-67fe-4b12-85fe-d81bc1fe4c6e', 'P005', 'Izin Usaha Penggabungan PM', 'Izin Usaha Penggabungan PM', '<p><strong>Izin Usaha Penggabungan PM</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Permohonan</li>\r\n	<li>Surat kuasa bagi pengurusan permohonan yang tidak dilakukan secara langsung oleh direktur/pimpinan perusahaan</li>\r\n	<li>Profil perusahaan</li>\r\n	<li>Fotocopy izin prinsip/perubahan penanaman modal</li>\r\n	<li>Fotocopy akta pendirian perusahaan</li>\r\n	<li>Fotocopy NPWP perusahaan</li>\r\n	<li>Kesepakatan penggabungan perusahaan yang dituangkan dalam bentuk kesepakatan perubahan kepemilikan saham dalam perseroan yang dituangkan dalam bentuk risalah rapat umum pemegang saham (RUPS / keputusan sirkuler seluruh pemegang saham / akta perubahan dalam bentuk keputusan / akta perubahan dalam bentuk keputusan rapat / berita acara)</li>\r\n	<li>Laporan kegiatan penanaman modal tahun terakhir</li>\r\n	<li>Legalitas pekerjaan</li>\r\n	<li>Bukti penguasaan atas tanah</li>\r\n	<li>IMB</li>\r\n	<li>Proposal dan presentasi rencana penggabungan perusahaan penanaman modal</li>\r\n	<li>Advis Pemanfaatan ruang</li>\r\n	<li>Izin lingkungan (amdal, UPL-UKL)</li>\r\n	<li>Rekomendasi instansi teknis terkait</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:40:32', NULL),
(7, '952daf7f-72b1-450e-8610-45b0592a6135', 'P006', 'Izin Usaha Perubahan PM', 'Izin Usaha Perubahan PM', '<p><strong>Izin Usaha Perubahan PM</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Permohonan</li>\r\n	<li>Surat kuasa bagi pengurusan permohonan yang tidak dilakukan secara langsung oleh direktur/pimpinan perusahaan</li>\r\n	<li>Profil perusahaan</li>\r\n	<li>Rencana perubahan penanaman modal</li>\r\n	<li>Fotocopy izin usaha penanaman modal</li>\r\n	<li>Laporan kegiatan penanaman modal tahun terakhir</li>\r\n	<li>Bukti penguasaan atas tanah</li>\r\n	<li>IMB</li>\r\n	<li>Proposal dan presentasi rencana perubahan investasi</li>\r\n	<li>Advis Pemanfaatan ruang</li>\r\n	<li>Izin lingkungan (amdal, UPL-UKL)</li>\r\n	<li>Rekomendasi instansi teknis terkait</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:41:07', NULL),
(8, 'd1e2f513-1abc-4761-97fd-5960bb3b428d', 'P007', 'Izin Perluasan PM', 'Izin Perluasan PM', '<p><strong>Izin Perluasan PM</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Permohonan</li>\r\n	<li>Surat kuasa bagi pengurusan permohonan yang tidak dilakukan secara langsung oleh direktur/pimpinan perusahaan</li>\r\n	<li>Profil perusahaan</li>\r\n	<li>Rencana perluasan penanaman modal</li>\r\n	<li>Fotocopy izin usaha penanaman modal</li>\r\n	<li>Laporan kegiatan penanaman modal tahun terakhir</li>\r\n	<li>Bukti penguasaan atas tanah</li>\r\n	<li>IMB</li>\r\n	<li>Proposal dan presentasi rencana perluasan investasi</li>\r\n	<li>Advis Pemanfaatan ruang</li>\r\n	<li>Izin lingkungan (amdal, UPL-UKL)</li>\r\n	<li>Rekomendasi instansi teknis terkait</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:21:55', NULL),
(9, '99b37d62-b57f-4759-b4c1-0e1c62aba8b0', 'P008', 'Izin usaha PM', 'Izin usaha PM', '<p><strong>Izin Usaha PM</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Permohonan</li>\r\n	<li>Surat kuasa bagi pengurusan permohonan yang tidak dilakukan secara langsung oleh direktur/pimpinan perusahaan</li>\r\n	<li>Profil perusahaan</li>\r\n	<li>Foto Copy Akta Pendirian Perusahaan</li>\r\n	<li>Surat keterangan domisili perusahaan</li>\r\n	<li>Foto Copy NPWP</li>\r\n	<li>Foto Copy KTP</li>\r\n	<li>Fotocopy SIUP, SITU, TDP</li>\r\n	<li>Fotocopy izin prinsip penanaman modal</li>\r\n	<li>Laporan kegiatan penanaman modal</li>\r\n	<li>Bukti penguasaan atas tanah</li>\r\n	<li>IMB</li>\r\n	<li>Proposal dan presentasi rencana investasi</li>\r\n	<li>Advis Pemanfaatan ruang</li>\r\n	<li>Izin lingkungan (amdal, UPL-UKL)</li>\r\n	<li>Rekomendasi instansi teknis terkait</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-13 06:36:46', NULL),
(10, '6ddbb507-8ab9-45c4-a171-7e4d2f9cc0f7', 'P009', 'Izin Penggabungan PM', 'Izin Penggabungan PM', '<p style=\"text-align:justify\"><strong>Izin Penggabungan PM</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Foto Copy Izin Prinsip/Izin usaha dan/atau perubahannya;</li>\r\n	<li style=\"text-align: justify;\">Foto Copy Akta Pendirian Perusahaan dan Perubahannya dilengkapi dengan Pengesahan dari Kementerian Hukum dan HAM;</li>\r\n	<li style=\"text-align: justify;\">Kesepakatan penggabungan perusahaan yang dituangkan dalam kesepakatan perubahan kepemilikan saham dalam perseroan yang dituangkan dalam bentuk RUPS atau akta perubahan dalam bentuk pernyataan Keputusan Rapat;</li>\r\n	<li style=\"text-align: justify;\">Foto Copy NPWP Perusahaan;</li>\r\n	<li style=\"text-align: justify;\">Tanda terima penyampaian LKPM dari BKPM/PDKPM dan LKPM periode terakhir;</li>\r\n	<li style=\"text-align: justify;\">Rekapitulasi data proyek sebelum dan sesudah penggabungan perusahaan;</li>\r\n	<li style=\"text-align: justify;\">Rekomendasi dari Instansi Teknis.</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 04:02:30', NULL),
(13, 'f552e7e2-892d-42ae-b673-e9e3c4d73752', 'P012', 'Izin Prinsip PM', 'Izin Prinsip PM', '<p style=\"text-align:justify\"><strong>Izin Prinsip PM</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<p style=\"text-align:justify\">a. Bukti Diri Pemohon</p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Foto Copy Akta Pendirian Perusahaan dan Perubahannya untuk Perusahaan.</li>\r\n	<li style=\"text-align: justify;\">Foto Copy Pengesahan Akta Perusahaan dari Kementerian Hukum dan HAM atau Pengesahan Anggaran Dasar Koperasi dari Menteri Koperasi.</li>\r\n	<li style=\"text-align: justify;\">Foto Copy NPWP.</li>\r\n	<li style=\"text-align: justify;\">Foto Copy KTP.</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\">b. Keterangan rencana kegiatan berupa :</p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Uraian proses produksi yang mencantumkan jenis bahan baku dan dilengkapi dengan diagram alir produksi/flow chart (sektor industri).</li>\r\n	<li style=\"text-align: justify;\">Uraian kegiatan usaha untuk sektor jasa dan penjelasan produk jasa yang dihasilkan.</li>\r\n	<li style=\"text-align: justify;\">Rekomendasi dari instansi pemerintah / advis peruntukkan ruang / lahan</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:23:38', NULL),
(14, '94205b71-e620-48d8-ab1d-ef9377d465e9', 'P013', 'Indeks Gangguan', 'Data Indeks Gangguan', '<h3 style=\"text-align:justify\">Indeks Gangguan</h3>\r\n\r\n<h4 style=\"text-align:justify\">Indeks 4</h4>\r\n\r\n<p style=\"text-align:justify\">dikategorikan sebagai Gangguan Besar dan terdiri dari:</p>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Industri perakitan kendaraan bermotor, Mobil</li>\r\n	<li style=\"text-align: justify;\">Industri Tekstil (Pemintalan, pertenunan, pengelantangan, pencelupan, percetakan, penyempurnaan)</li>\r\n	<li style=\"text-align: justify;\">Industri Farmasi, Kimia</li>\r\n	<li style=\"text-align: justify;\">Industri Penyamakan/pengawetan kulit</li>\r\n	<li style=\"text-align: justify;\">Industri kertas/pulp</li>\r\n	<li style=\"text-align: justify;\">Industri Batu Baterai Kering</li>\r\n	<li style=\"text-align: justify;\">Industri Kosmetika</li>\r\n	<li style=\"text-align: justify;\">Industri Logam Elektro Platting, pandai emas</li>\r\n	<li style=\"text-align: justify;\">Industri Separato ACCU</li>\r\n	<li style=\"text-align: justify;\">Industri Marmer</li>\r\n	<li style=\"text-align: justify;\">Industri Karoseri</li>\r\n	<li style=\"text-align: justify;\">Industri Besi, Baja, Timah, Peleburan Logam</li>\r\n	<li style=\"text-align: justify;\">Pertukangan Besi, Pertukangan Kayu, Pembakaran Genteng, penggergajian kayu, pemahatan batu</li>\r\n	<li style=\"text-align: justify;\">Industri Minyak goreng, Margarine</li>\r\n	<li style=\"text-align: justify;\">Industri Cuka</li>\r\n	<li style=\"text-align: justify;\">Industri plastik</li>\r\n	<li style=\"text-align: justify;\">Industri tepung beras, tapioka, ubi jalar, ikan, terigu</li>\r\n	<li style=\"text-align: justify;\">Industri kayu lapis</li>\r\n	<li style=\"text-align: justify;\">Industri garmen dengan pencucian</li>\r\n	<li style=\"text-align: justify;\">Industri pemberantasan hama</li>\r\n	<li style=\"text-align: justify;\">Industri cat, pernis, Lak</li>\r\n	<li style=\"text-align: justify;\">Industri Sabun, tapal gigi</li>\r\n	<li style=\"text-align: justify;\">Industri perekat</li>\r\n	<li style=\"text-align: justify;\">Industri pembersih/penggilingan minyak bumi</li>\r\n	<li style=\"text-align: justify;\">Industri kaca lembaran</li>\r\n	<li style=\"text-align: justify;\">Industri pengecoran</li>\r\n	<li style=\"text-align: justify;\">Industri Logam</li>\r\n	<li style=\"text-align: justify;\">Industri paku, engsel dan sejenisnya</li>\r\n	<li style=\"text-align: justify;\">Industri suku cadang</li>\r\n	<li style=\"text-align: justify;\">Industri transformator</li>\r\n	<li style=\"text-align: justify;\">Industri vulkanisir ban</li>\r\n	<li style=\"text-align: justify;\">Industri panel listrik</li>\r\n	<li style=\"text-align: justify;\">Industri kapal perahu</li>\r\n	<li style=\"text-align: justify;\">Industri kendaraan roda dua atau lebih</li>\r\n	<li style=\"text-align: justify;\">Industri komponen dan perlengkapan kendaraan bermotor, mobil</li>\r\n	<li style=\"text-align: justify;\">Industri sepeda</li>\r\n	<li style=\"text-align: justify;\">Industri pembekuan/pengalengan ikan/udang, cumi-cumi, kepiting</li>\r\n	<li style=\"text-align: justify;\">Industri pengasapan karet, reinling dan crumb rubber</li>\r\n	<li style=\"text-align: justify;\">Pabrik Teh, Ban enternit</li>\r\n	<li style=\"text-align: justify;\">Bengkel kendaraan bermotor, mobil</li>\r\n	<li style=\"text-align: justify;\">Bengkel bubut, bengkel galangan kapal</li>\r\n	<li style=\"text-align: justify;\">Industri radio, tv dan sejenisnya</li>\r\n	<li style=\"text-align: justify;\">Tower pemancar, Base Transceiver Signal</li>\r\n	<li style=\"text-align: justify;\">Hotel bertaraf internasional</li>\r\n	<li style=\"text-align: justify;\">Perumahan</li>\r\n	<li style=\"text-align: justify;\">Bioskop</li>\r\n	<li style=\"text-align: justify;\">Diskotik/Karaoke/Bar/Panti pijat</li>\r\n	<li style=\"text-align: justify;\">Pembibitan ayam ras</li>\r\n	<li style=\"text-align: justify;\">Peternakan Ayam, Unggas, Sapi perah</li>\r\n	<li style=\"text-align: justify;\">Rumah potong unggas, Hewan</li>\r\n	<li style=\"text-align: justify;\">SPBU</li>\r\n	<li style=\"text-align: justify;\">Pangkalan Minyak Tanah, Gas</li>\r\n	<li style=\"text-align: justify;\">Garasi Anggkutan Barang dan Orang</li>\r\n	<li style=\"text-align: justify;\">Penimbunan Barang bekas/Besi tua</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">Indeks 3</h4>\r\n\r\n<p style=\"text-align:justify\">dikategorikan sebagai Gangguan Sedang dan terdiri dari:</p>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Pabrik Mie, Tahu, Tempe, Macaroni, Spagetti dan sejenisnya</li>\r\n	<li style=\"text-align: justify;\">Pabrik sepatu</li>\r\n	<li style=\"text-align: justify;\">Pabrik kayu</li>\r\n	<li style=\"text-align: justify;\">Percetakan</li>\r\n	<li style=\"text-align: justify;\">Industri bumbu masak</li>\r\n	<li style=\"text-align: justify;\">Industri pengolahan dan pengawetan daging</li>\r\n	<li style=\"text-align: justify;\">Industri pengolahan buah-buahahn dan sayur-sayuran</li>\r\n	<li style=\"text-align: justify;\">Industri pengupasan dan pembersihan kopi/kacang kacangan / ubi ubian</li>\r\n	<li style=\"text-align: justify;\">Industri Roti, Kue dan sejenisnya</li>\r\n	<li style=\"text-align: justify;\">Industri bubuk coklat</li>\r\n	<li style=\"text-align: justify;\">Industri pertenunan</li>\r\n	<li style=\"text-align: justify;\">Industri karung goni, karung plastik dan sejenisnya</li>\r\n	<li style=\"text-align: justify;\">Industri pakan ternak</li>\r\n	<li style=\"text-align: justify;\">Industri penggergajian kayu</li>\r\n	<li style=\"text-align: justify;\">Industri porselin</li>\r\n	<li style=\"text-align: justify;\">Industri barang gelas</li>\r\n	<li style=\"text-align: justify;\">Industri keramik</li>\r\n	<li style=\"text-align: justify;\">Pabrik Bata Merah, Batako</li>\r\n	<li style=\"text-align: justify;\">Industri alat pertanian, pertukangan</li>\r\n	<li style=\"text-align: justify;\">Industri alat dapur dari alumunium</li>\r\n	<li style=\"text-align: justify;\">Industri komponen elektronika</li>\r\n	<li style=\"text-align: justify;\">Industri kabel listrik dan telepon</li>\r\n	<li style=\"text-align: justify;\">Industri lampu dan perlengkapannya</li>\r\n	<li style=\"text-align: justify;\">Industri susu</li>\r\n	<li style=\"text-align: justify;\">Meubeler</li>\r\n	<li style=\"text-align: justify;\">Rumah Bilyard</li>\r\n	<li style=\"text-align: justify;\">Supermarket/swalayan</li>\r\n	<li style=\"text-align: justify;\">Distributor / agen</li>\r\n	<li style=\"text-align: justify;\">Perbankan</li>\r\n	<li style=\"text-align: justify;\">Hotel berbintang, restoran/Rumah Makan / Kafe, Foodcort</li>\r\n	<li style=\"text-align: justify;\">Galangan/Dok Kapal</li>\r\n	<li style=\"text-align: justify;\">Pencucian pakaian, karpet</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">Indeks 2</h4>\r\n\r\n<p style=\"text-align:justify\">dikategorikan sebagai Gangguan Kecil dan terdiri dari:</p>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Pabrik es batu</li>\r\n	<li style=\"text-align: justify;\">Pabrik garam</li>\r\n	<li style=\"text-align: justify;\">Tambak udang, ikan</li>\r\n	<li style=\"text-align: justify;\">Perusahaan pencucican kendaraan</li>\r\n	<li style=\"text-align: justify;\">Perusahaan strum accu</li>\r\n	<li style=\"text-align: justify;\">Konveksi</li>\r\n	<li style=\"text-align: justify;\">Industri kerajinan rumah tangga</li>\r\n	<li style=\"text-align: justify;\">Industri perakitan elektronika</li>\r\n	<li style=\"text-align: justify;\">Industri sirop, Minuman, Es Cream, Es Lilin</li>\r\n	<li style=\"text-align: justify;\">Industri Gula Merah</li>\r\n	<li style=\"text-align: justify;\">Industri perajutan</li>\r\n	<li style=\"text-align: justify;\">Industri kerupuk, getas, amplang, terasi/petis, rusip, kericu, kecap/tauco</li>\r\n	<li style=\"text-align: justify;\">Industri garmen tanpa pencucian</li>\r\n	<li style=\"text-align: justify;\">Industri alat musik</li>\r\n	<li style=\"text-align: justify;\">Industri mainan anak-anak</li>\r\n	<li style=\"text-align: justify;\">Industri alat tulis/gambar</li>\r\n	<li style=\"text-align: justify;\">Industri permata/barang perhiasan</li>\r\n	<li style=\"text-align: justify;\">Industri jamu</li>\r\n	<li style=\"text-align: justify;\">Industri goreng bawang</li>\r\n	<li style=\"text-align: justify;\">Hotel Melati/Losmen/Penginapan/Wisma/Rumah Kos</li>\r\n	<li style=\"text-align: justify;\">Tempat rekreasi, Permainan anak-anak</li>\r\n	<li style=\"text-align: justify;\">Rumah sakit, Rumah bersalin, Balai pengobatan, Apotek, Optikal, Laboratorium Kesehatan, Pengobatan tradisional, Toko obat</li>\r\n	<li style=\"text-align: justify;\">Kolam renang, gedung olah raga</li>\r\n	<li style=\"text-align: justify;\">Gedung yang dikomersil, toilet yang dikomersil</li>\r\n	<li style=\"text-align: justify;\">Warung makan, kantin, katering, warung minuman</li>\r\n	<li style=\"text-align: justify;\">Mini Market, toko-toko dagang, Kantor Dagang Umum</li>\r\n	<li style=\"text-align: justify;\">Salon, Gunting Rambut, Penjahit Pakaian</li>\r\n	<li style=\"text-align: justify;\">Depot kayu/bahan bangunan, pembuatan ukiran kerajinan kayu</li>\r\n	<li style=\"text-align: justify;\">Ruang pamer kendaraan, wartel, warnet, percetakan ringan tanpa mesin, perbaikan elektronik</li>\r\n	<li style=\"text-align: justify;\">Pergudangan</li>\r\n	<li style=\"text-align: justify;\">Bengkel sepeda</li>\r\n	<li style=\"text-align: justify;\">Tambal Ban</li>\r\n</ul>\r\n', NULL, NULL, 94, '2023-09-11 03:18:30', NULL),
(15, 'da7b3876-771f-4700-908a-909bc4d28bd7', 'P014', 'Standard Biaya Retribusi', 'Standard Biaya Retribusi', '<p><strong>Standard Biaya Retribusi Surat Izin Gangguan :</strong></p>\r\n<ul>\r\n    <li>Luas Usaha ≤ 50 M² dikenakan tarif sebesar Rp. 3.500 per M²</li>\r\n    <li>Luas Usaha 50 M² - 100 M² dikenakan tarif sebesar Rp. 3.000 per M²</li>\r\n    <li>Luas Usaha >100M² - 500M² dikenakan tarif sebesar Rp. 2.500 Per M²</li>\r\n    <li>Luas Usaha >500M² dikenakan tarif sebesar Rp. 2.000 per M²</li>\r\n</ul>\r\n', NULL, NULL, 94, '2023-09-13 06:43:56', NULL),
(16, '73c25809-6f1c-4267-b9eb-ca17984d2082', 'P015', 'Persyaratan Administrasi', 'Persyaratan Administrasi', '<p><strong>Persyaratan Administrasi:</strong></p>\r\n\r\n<ol>\r\n	<li>Mengisi Formulir Permohonan yang ditandatangani oleh pemohon di atas meterai dan diketahui oleh lurah serta camat.</li>\r\n	<li>Foto Copy KTP pemohon/pemilik usaha/penanggung jawab atau Surat izin Tinggal Sementara (khusus untuk Penanaman Modal Asing).</li>\r\n	<li>Pas foto Ukuran 3 x 4 sebanyak 4 lembar.</li>\r\n	<li>Foto Copy Pelunasan PBB.</li>\r\n	<li>Fotocopy Akta Pendirian Perusahaan bagi yang berbadan hukum (khusus untuk Perseroan Terbatas harus melampirkan pengesahan pendirian perusahaan dari Menteri Hukum dan HAM).</li>\r\n	<li>Foto Copy Izin Mendirikan Bangunan (IMB), sesuai kegiatan usaha.</li>\r\n	<li>Identitas Pemohon dan Perusahaan.</li>\r\n	<li>Surat pernyataan tidak keberatan (persetujuan) dari tetangga / Lingkungan.</li>\r\n	<li>Surat Pernyataan Penggunaan Tanah/bangunan, jika pemohon bukan sebagai pemilik tanah/bangunan, dengan melampirkan akta otentik yang menerangkan hubungan hukum antara pemohon dengan obyek tanah/bangunan, dalam bentuk akta perjanjian sewa menyewa atau perjanjian pinjam pakai atau dalam bentuk perjanjian lainnya.</li>\r\n	<li>Surat Pernyataan pencegahan/pengendalian gangguan dan pencemaran lingkungan (dokumen Amdal atau UKL/UPL untuk usaha tertentu).</li>\r\n	<li>Denah lokasi tempat usaha.</li>\r\n	<li>Surat Kuasa apabila dikuasakan pengurusannya (dibubuhi meterai 6000 dan foto copy KTP).</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih</em></p>\r\n', NULL, NULL, 94, '2023-09-13 06:40:26', NULL),
(17, '832222a8-4eae-4e05-be77-5190f528e0a6', 'P016', 'Izin Gangguan', 'Izin Gangguan', '<p><strong>Izin Gangguan</strong></p>\r\n<ol>\r\n    <li><strong>Persyaratan Administrasi</strong></li>\r\n</ol>\r\n<ol>\r\n    <li>Fotocopy Akta Pendirian Perseroan Terbatas dan Pengesahan badan hukum dari pejabat yang berwenang dan akta perubahannya (jika ada),\r\n', NULL, NULL, 94, '2023-09-11 03:44:42', NULL),
(18, '73dd9107-0024-4842-af5a-9759e5559cb9', 'P017', 'Izin Usaha Jasa Kontruksi', 'Izin Usaha Jasa Kontruksi', '<p><strong>Izin Usaha Jasa Kontruksi</strong></p>\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n<ol>\r\n    <li>Mengisi Formulir Permohonan yang ditandatangani oleh pemohon.</li>\r\n    <li>Foto Copy KTP pemohon/pemilik usaha/penanggung jawab atau Surat izin Tinggal Sementara (khusus untuk Penanaman Modal Asing).</li>\r\n    <li>Pas foto Ukuran 3 x 4 sebanyak 3 lembar.</li>\r\n    <li>Foto Copy Pelunasan PBB.</li>\r\n    <li>Fotocopy Akta Pendirian Perusahaan bagi yang berbadan hukum (khusus untuk Perseroan Terbatas harus melampirkan pengesahan pendirian perusahaan dari Menteri Hukum dan HAM).</li>\r\n    <li>Foto Copy NPWP</li>\r\n    <li>Surat Kuasa apabila dikuasakan pengurusannya (dibubuhi meterai 6000 dan foto copy KTP).</li>\r\n</ol>\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:39:49', NULL),
(22, '90b6bf7d-39f0-4d2a-b7dd-49e5b797c0c7', 'P018', 'Izin Lokasi', 'Izin Lokasi', '<p><strong>Izin Lokasi</strong></p>\r\n\r\n<ol>\r\n	<li><strong>Persyaratan Administrasi:</strong></li>\r\n</ol>\r\n\r\n<ul>\r\n	<li>Mengisi Formulir Permohonan yang ditandatangani oleh pemohon.</li>\r\n	<li>Foto Copy KTP pemohon/pemilik usaha/penanggung jawab atau Surat izin Tinggal Sementara (khusus untuk Penanaman Modal Asing).</li>\r\n	<li>Pas foto Ukuran 4 x 6 sebanyak 4 lembar.</li>\r\n	<li>Foto Copy Pelunasan PBB.</li>\r\n	<li>Foto Copy Akta Pendirian Perusahaan bagi yang berbadan hukum (khusus untuk Perseroan Terbatas harus melampirkan pengesahan pendirian perusahaan dari Menteri Hukum dan HAM).</li>\r\n	<li>Foto Copy NPWP.</li>\r\n	<li>Foto Copy Surat Izin Gangguan (SIG).</li>\r\n	<li>Daftar susunan Direksi dan Penanggung Jawab.</li>\r\n	<li>Laporan Kegiatan tahunan bagi perpanjangan.</li>\r\n	<li>Data Administrasi Perusahaan.</li>\r\n	<li>Surat Kuasa apabila dikuasakan pengurusannya (dibubuhi meterai 6000 dan foto copy KTP).</li>\r\n	<li>Foto Copy Sertifikat Badan Usaha (SBU) yang diterbitkan LPJK.</li>\r\n</ul>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:50:19', NULL),
(23, 'a702dae6-5bdd-425b-8208-2e63fb078314', 'P019', 'IPPL', 'IPPL', '<p style=\"text-align:justify\"><strong>IPPL</strong></p>\r\n\r\n<p style=\"text-align:justify\"><strong>Persyaratan Administrasi :</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Mengisi Formulir Permohonan yang ditandatangani oleh pemohon.</li>\r\n	<li style=\"text-align: justify;\">Foto Copy KTP pemohon/pemilik usaha/penanggung jawab atau Surat izin Tinggal Sementara (khusus untuk Penanaman Modal Asing).</li>\r\n	<li style=\"text-align: justify;\">Pas foto Ukuran 3 x 4 sebanyak 3 lembar.</li>\r\n	<li style=\"text-align: justify;\">Foto Copy Pelunasan PBB.</li>\r\n	<li style=\"text-align: justify;\">Fotocopy Akta Pendirian Perusahaan bagi yang berbadan hukum (khusus untuk Perseroan Terbatas harus melampirkan pengesahan pendirian perusahaan dari Menteri Hukum dan HAM).</li>\r\n	<li style=\"text-align: justify;\">Foto Copy NPWP.</li>\r\n	<li style=\"text-align: justify;\">Uraian rencana proyek yang akan dibangun.</li>\r\n	<li style=\"text-align: justify;\">Foto Copy Advis Planing dari Dinas Pekerjaan Umum dan Tata Ruang.</li>\r\n	<li style=\"text-align: justify;\">Foto Copy Surat Tanah.</li>\r\n	<li style=\"text-align: justify;\">Surat Kuasa apabila dikuasakan pengurusannya (dibubuhi meterai 6000 dan foto copy KTP).</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:40:13', NULL),
(24, '763bb5ed-b3c2-40e1-a9e0-0d7347505e7e', 'P020', 'Izin Umot', 'Izin Umot', '<p><strong>Izin Umot</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Surat permohonan</li>\r\n	<li>Fotokopi akta pendirian badan usaha perorangan yang sah sesuai ketentuan peraturan perundang-undangan</li>\r\n	<li>Susunan Direksi/Pengurus dan Komisaris/Badan Pengawas dalam hal permohonan bukan perseorangan</li>\r\n	<li>Fotokopi KTP/identitas pemohon dan/atau Direksi/Pengurus dan Komisaris/Badan Pengawas</li>\r\n	<li>Pernyataan pemohon dan/atau Direksi/Pengurus dan Komisaris/Badan Pengawas tidak pernah terlibat pelanggaran peraturan perundang-undangan di bidang farmasi</li>\r\n	<li>Fotokopi bukti penguasaan tanah dan bangunan</li>\r\n	<li>Surat Tanda Daftar Perusahaan dalam hal permohonan bukan perseorangan</li>\r\n	<li>Fotokopi Surat Izin Usaha Perdagangan dalam hal permohonan bukan perseorangan</li>\r\n	<li>Fotokopi Nomor Pokok Wajib Pajak</li>\r\n	<li>Fotokopi Surat Keterangan Domisili</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:39:14', NULL),
(25, '414ba49e-ff21-4178-b971-65a15f5f1528', 'P021', 'Izin Tukang Gigi', 'Izin Tukang Gigi', '<p><strong>Izin Tukang Gigi</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Biodata Tukang Gigi</li>\r\n	<li>Izin Tukang Gigi</li>\r\n	<li>Fotokopi KTP</li>\r\n	<li>Surat Keterangan Kepala Desa/Lurah tempat melakukan pekerjaan sebagai Tukang Gigi</li>\r\n	<li>Surat Rekomendasi dari organisasi Tukang Gigi setempat yang diakui oleh pemerintah</li>\r\n	<li>Surat Keterangan Sehat dari dokter pemerintah yang memiliki surat izin praktek</li>\r\n	<li>Pas Foto Terbaru ukuran 4x6 cm sebanyak 2 lembar</li>\r\n	<li>Rekomendasi dari Kepala Dinas Kesehatan atau pejabat yang ditunjuk</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:38:33', NULL),
(26, '20eda23e-8d1a-4b0d-a709-b6db217b2b5a', 'P022', 'Izin Toko Obat', 'Izin Toko Obat', '<p><strong>Izin Toko Obat</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Fotokopi KTP Pemohon (TTK) atau keterangan domisili dari Camat setempat bagi yang memiliki KTP di luar Pangkalpinang</li>\r\n	<li>Fotokopi KTP Pemilik sarana atau keterangan domisili dari Camat setempat bagi yang memiliki KTP di luar Pangkalpinang</li>\r\n	<li>Pas Photo TTK berwarna latar belakang merah ukuran 4x6 cm sebanyak 4 lembar.</li>\r\n	<li>Fotokopi Surat Izin Praktik (SIP) TTK yang berlaku.</li>\r\n	<li>Denah bangunan dan denah alamat toko obat.</li>\r\n	<li>Surat Izin dari atasan bagi pemohon Pegawai Negeri, Anggota ABRI dan Pegawai Instansi Pemerintah lainnya.</li>\r\n	<li>Surat Pernyataan kesediaan TTK sebagai penanggungjawab teknis toko obat.</li>\r\n	<li>Surat Pernyataan kerjasama TTK dengan pemilik sarana toko obat.</li>\r\n	<li>Fotokopi Izin Mendirikan Bangunan (IMB).</li>\r\n	<li>Mengembalikan surat izin yang lama (untuk perpanjangan, pindah alamat atau ganti penanggungjawab).</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:38:01', NULL),
(27, 'a3c0da1a-7db5-4e5c-8c84-e68a763516f1', 'P023', 'Izin Toko Alat Kesehatan', 'Izin Toko Alat Kesehatan', '<p style=\"text-align:justify\"><strong>Izin Toko Alat Kesehatan</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Fotokopi KTP Pemohon (TTK) atau keterangan domisili dari Camat setempat bagi yang memiliki KTP di luar Pangkalpinang</li>\r\n	<li style=\"text-align: justify;\">Fotokopi KTP Pemilik sarana atau keterangan domisili dari Camat setempat bagi yang memiliki KTP di luar Pangkalpinang</li>\r\n	<li style=\"text-align: justify;\">Pas Photo TTK berwarna latar belakang merah ukuran 4x6 cm sebanyak 4 lembar.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Surat Izin Praktik (SIP) TTK yang berlaku.</li>\r\n	<li style=\"text-align: justify;\">Denah bangunan dan denah alamat toko Alat Kesehatan.</li>\r\n	<li style=\"text-align: justify;\">Surat Izin dari atasan bagi pemohon Pegawai Negeri, Anggota ABRI dan Pegawai Instansi Pemerintah lainnya.</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan kesediaan TTK sebagai penanggungjawab teknis toko Alat Kesehatan.</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan kerjasama TTK dengan pemilik sarana toko Alat Kesehatan.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Izin Mendirikan Bangunan (IMB).</li>\r\n	<li style=\"text-align: justify;\">Mengembalikan surat izin yang lama (untuk perpanjangan, pindah alamat atau ganti penanggungjawab).</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:37:17', NULL),
(28, '746b33a9-4030-4952-b01b-787dec2398c3', 'P024', 'Izin STPT', 'Izin STPT', '<p style=\"text-align:justify\"><strong>Izin STPT</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Biodata penyehat tradisional.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi KTP Pemohon (pemilik sarana) atau keterangan domisili dari Camat setempat bagi pemohon yang memiliki KTP di luar Pangkalpinang.</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan lurah setempat.</li>\r\n	<li style=\"text-align: justify;\">Peta lokasi usaha dan denah ruangan.</li>\r\n	<li style=\"text-align: justify;\">Rekomendasi dari asosiasi/organisasi profesi dibidang pengobatan tradisional yang bersangkutan.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi sertifikat/ Ijazah pengobat tradisional (bila ada).</li>\r\n	<li style=\"text-align: justify;\">Surat pengantar puskesmas setempat, surat keterangan sehat semua pegawai dan KTP pegawai.</li>\r\n	<li style=\"text-align: justify;\">Pas photo terbaru berwarna latar belakang merah ukuran 4x6 cm sebanyak 4 (empat) lembar.</li>\r\n	<li style=\"text-align: justify;\">Rekomendasi Kejaksaan Kota bagi pengobat tradisional klasifikasi supranatural dan Kantor Departemen Agama Kota bagi pengobat tradisional klasifikasi pendekatan agama.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Izin Mendirikan Bangunan (IMB).</li>\r\n	<li style=\"text-align: justify;\">Mengembalikan surat izin yang lama (untuk perpanjangan atau pindah alamat).</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:36:37', NULL),
(29, '10338f97-f2b4-4395-872f-edf5bf3d6784', 'P025', 'Izin Radiologi', 'Izin Radiologi', '<p><strong>Izin Radiologi</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Akte pendirian perusahaan untuk penyelenggara bukan perorangan.</li>\r\n	<li>Fotokopi KTP Pemohon (pemilik sarana) atau keterangan domisili dari Camat setempat bagi pemohon yang memiliki KTP di luar Pangkalpinang.</li>\r\n	<li>Data penanggungjawab :\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li>fotokopi ktp penanggungjawab instalasi radiologi</li>\r\n		<li>fotokopi ijazah penanggungjawab yang dilegalisir</li>\r\n		<li>Surat pernyataan kesanggupan sebagai penanggung jawab</li>\r\n		<li>fotokopi STR dan SIP penggungjawab</li>\r\n		<li>Pas Photo berwarna latar belakang merah ukuran 4x6 cm sebanyak 2 lembar.</li>\r\n	</ol>\r\n	</li>\r\n	<li>Struktur organisasi instalasi radiologi</li>\r\n	<li>Daftar ketenagaan dengan mencantumkan nama, alamat, lulusan dan tanggal lulus serta fotokopi Surat Izin Kerja (SIK) dan Surat Izin Bekerja (SIB) dari BAPETEN untuk petugas proteksi radiasi (PPR) yang masih berlaku.</li>\r\n	<li>Data denah bangunan, ukuran, konstruksi dan proteksi ruangan</li>\r\n	<li>Denah lokasi tempat usaha</li>\r\n	<li>Surat perjanjian kerja sama pemilik sarana dan penanggung jawab instalasi radiologi</li>\r\n	<li>Daftar peralatan dan spesifikasi teknis alat</li>\r\n	<li>Berita Acara Uji fungsi alat</li>\r\n	<li>Surat izin importir dari BAPETEN (untuk alat yang menggunakan radiasi pengion/sinar x)\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li>Surat izin pemanfaatan tenaga nuklir dari BAPETEN</li>\r\n		<li>Daftar petugas proteksi radiasi</li>\r\n		<li>Daftar pekerja radiasi</li>\r\n		<li>Data alat ukur radiasi</li>\r\n	</ol>\r\n	</li>\r\n	<li>Rencana bangunan beserta kelengkapannya</li>\r\n	<li>Rencana sarana penampungan / pengolahan limbah cair, padat dan kimia</li>\r\n	<li>Fotokopi Izin Mendirikan Bangunan (IMB).</li>\r\n	<li>Mengembalikan surat izin yang lama (untuk perpanjangan, pindah alamat atau ganti penanggungjawab)</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:26:25', NULL),
(30, 'eb8904f2-82d3-4253-90b8-05d42d16f633', 'P026', 'Izin Puskesmas', 'Izin Puskesmas', '<p style=\"text-align:justify\"><strong>Izin Puskesmas</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Fotocopi sertifikat tanah atau bukti kepemilikan tanah yang sah</li>\r\n	<li style=\"text-align: justify;\">Fotokopi IMB</li>\r\n	<li style=\"text-align: justify;\">Dokumen pengelolaan lingkungan sesuai ketentuan peraturan perundang-undangan</li>\r\n	<li style=\"text-align: justify;\">Surat keputusan walikota terkait kategori Puskesmas</li>\r\n	<li style=\"text-align: justify;\">Studi kelayakan untuk Puskesmas yang baru didirikan atau akan dikembangkan</li>\r\n	<li style=\"text-align: justify;\">Profil Puskesmas yang meliputi aspek lokasi, bangunan, prasarana, peralatan kesehatan, ketenagaan, dan pengorganisasian untuk Puskesmas yang mengajukan permohonan perpanjangan izin</li>\r\n	<li style=\"text-align: justify;\">Persyaratan lainnya sesuai dengan peraturan daerah setempat</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:24:24', NULL),
(31, '0fae55af-546b-4fab-a782-401875cb0a06', 'P027', 'Izin Optik', 'Izin Optik', '<p style=\"text-align:justify\"><strong>Izin Optik</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Akte pendirian perusahaan untuk penyelenggara yang berbentuk perusahaan bukan perorangan.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi KTP Pemohon atau keterangan domisili dari Camat setempat bagi pemohon yang memiliki KTP di luar Pangkalpinang.</li>\r\n	<li style=\"text-align: justify;\">Surat pernyataan kesediaan Refraksionis Optisien (RO) sebagai penanggung jawab dengan kelengkapan :\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li>Surat perjanjian kerjasama pemilik sarana dengan RO</li>\r\n		<li>Fotokopi KTP atau keterangan domisili</li>\r\n		<li>Fotokopi ijazah RO yang dilegalisir</li>\r\n		<li>Surat keterangan sehat dari dokter atau puskesmas</li>\r\n		<li>Pasfoto berwarna latar merah ukuran 4x6 sebanyak 4 lembar</li>\r\n		<li>Fotokopi STRRO yang dilegalisir</li>\r\n		<li>Fotokopi Surat Izin Kerja RO yang masih berlaku</li>\r\n	</ol>\r\n	</li>\r\n	<li style=\"text-align: justify;\">Surat pernyataan kerjasama dengan Laboratorium Optik bila optikal tidak memiliki laboratorium sendiri.</li>\r\n	<li style=\"text-align: justify;\">Daftar sarana dan peralatan yang digunakan</li>\r\n	<li style=\"text-align: justify;\">Daftar pegawai beserta tugas dan fungsinya</li>\r\n	<li style=\"text-align: justify;\">Peta lokasi tempat domisili optikal/laboratorium optik.</li>\r\n	<li style=\"text-align: justify;\">Denah ruangan</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan dari Orgasisasi Profesi/asosiasi setempat yang menyatakan bahwa RO yang diajukan menjadi penanggungjawab dari optikal tersebut dan diketahui oleh asosiasi pengusaha optikal setempat</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Izin Mendirikan Bangunan (IMB).</li>\r\n	<li style=\"text-align: justify;\">Mengembalikan surat izin yang lama (untuk perpanjangan, pindah alamat atau ganti penanggungjawab)</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 04:01:51', NULL),
(32, 'ce317ca7-e889-43e1-b716-13d20c258e0d', 'P028', 'Izin Operasional Rumah Sakit', 'Izin Operasional Rumah Sakit', '<p><strong>Izin Operasional Rumah Sakit</strong></p>\r\n\r\n<ol>\r\n	<li>Fotokopi izin mendirikan rumah sakit</li>\r\n	<li>Daftar sarana dan prasarana rumah sakit sesuai peraturan perundang-undangan yang berlaku menurut jenis dan klasifikasinya.</li>\r\n	<li>Daftar peralatan medis dan non medis</li>\r\n	<li>Daftar sumber daya manusia</li>\r\n	<li>Data administrasi dan manajemen.</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 04:01:01', NULL),
(33, 'a25b29a0-fda8-4f5c-9ada-cf1708ace157', 'P029', 'Izin Mendirikan Rumah Sakit', 'Izin Mendirikan Rumah Sakit', '<p style=\"text-align:justify\"><strong>Izin Mendirikan Rumah Sakit</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>Persyaratan:</strong></li>\r\n</ol>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Studi Kelayakan:\r\n	<ul>\r\n		<li>Analisa Kebutuhan Pelayanan Rencana Pengembangan.</li>\r\n		<li>Analisa Keuangan.</li>\r\n		<li>Program Fungsi, Kebutuhan ruang, Kebutuhan peralatan, Kebutuhan tenaga dan mendapatkannya, Kebutuhan rencana Kelas Rumah Sakit.</li>\r\n	</ul>\r\n	</li>\r\n	<li style=\"text-align: justify;\">Master Plan.</li>\r\n	<li style=\"text-align: justify;\">Status Kepemilikan.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Akte Badan Hukum.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Sertifikat Tanah dan Luas Tanah.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Izin Mendirikan (IMB).</li>\r\n	<li style=\"text-align: justify;\">Persyaratan Pengolahan Limbah (Dokumen UKL - UPL).</li>\r\n	<li style=\"text-align: justify;\">Penamaan.</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan Tunduk kepada Peraturan Perundang-undangan yang berlaku dari Pemilik dan Penanggungjawab Rumah Sakit.</li>\r\n	<li style=\"text-align: justify;\">Daftar Isian Pendirian Rumah Sakit.</li>\r\n	<li style=\"text-align: justify;\">Rekomendasi PERSI.</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:51:19', NULL),
(34, 'e7fa6c56-bf15-4b03-b6ed-b6dfcc8a6f1a', 'P030', 'Izin Laboratorium Klinik', 'Izin Laboratorium Klinik', '<p><strong>Izin Laboratorium Klinik</strong></p>\r\n<ol>\r\n    <li><strong>Persyaratan Administrasi:</strong></li>\r\n</ol>\r\n<ul>\r\n    <li>Fotokopi Kartu Tanda Penduduk (KTP) pemilik sarana atau surat keterangan domisili dari camat setempat bagi yang memiliki KTP di luar Pangkalpinang.</li>\r\n    <li>Fotokopi Kartu Tanda Penduduk (KTP) penanggungjawab laboratorium atau surat keterangan domisili dari camat setempat bagi yang memiliki KTP di luar Pangkalpinang.</li>\r\n    <li>Fotokopi Akte pendirian perusahaan untuk penyelenggara bukan perorangan.</li>\r\n    <li>Denah alamat/lokasi dengan situasi sekitarnya.</li>\r\n    <li>Denah bangunan/ruangan yang diusulkan.</li>\r\n    <li>Rencana sarana penampungan/pengolahan limbah cair, padat, dan kimia.</li>\r\n    <li>Surat keterangan penggunaan penerangan dan air.</li>\r\n    <li>Surat pernyataan kesanggupan masing-masing tenaga teknis (Form. A2).</li>\r\n    <li>Surat pernyataan kesanggupan masing-masing tenaga teknis/administrasi.</li>\r\n    <li>Surat pernyataan kesediaan mengikuti program pemantapan mutu eksternal (Form. A3).</li>\r\n    <li>Data kelengkapan bangunan (Form. A4).</li>\r\n    <li>Data kelengkapan peralatan (Form. A5).</li>\r\n    <li>Daftar jenis kemampuan pemeriksaan laboratorium.</li>\r\n    <li>Struktur organisasi Laboratorium Klinik.</li>\r\n    <li>Surat keterangan dari BLH terkait masalah pengolahan limbah.</li>\r\n    <li>Fotokopi Izin Mendirikan Bangunan (IMB).</li>\r\n    <li>Mengembalikan surat izin yang lama (untuk perpanjangan, pindah alamat, atau ganti penanggungjawab).</li>\r\n</ul>\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:46:46', NULL),
(35, '474cd46d-e49e-4db5-8386-6238e42b04da', 'P031', 'Izin Klinik', 'IZIN KLINIK', '<p style=\"text-align:justify\"><strong>Izin Klinik</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>Persyaratan Administrasi:</strong></li>\r\n</ol>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Fotokopi Akta pendirian perusahaan untuk Klinik Pratama Rawat Inap dan Klinik Utama.</li>\r\n	<li style=\"text-align: justify;\">Data Pemohon/pemilik sarana:\r\n	<ul>\r\n		<li>Fotocopy KTP</li>\r\n		<li>NPWP</li>\r\n		<li>Pas Photo 4X6 cm sebanyak 2 lembar</li>\r\n	</ul>\r\n	</li>\r\n	<li style=\"text-align: justify;\">Surat pernyataan status kepemilikan di atas materai 6000.</li>\r\n	<li style=\"text-align: justify;\">Data tempat usaha:\r\n	<ul>\r\n		<li>Fotocopy IMB</li>\r\n		<li>SIG</li>\r\n		<li>Bukti kepemilikan atas tanah dan bangunan/sertifikat</li>\r\n		<li>Gambar Denah Bangunan dan Denah Lokasi.</li>\r\n	</ul>\r\n	</li>\r\n	<li style=\"text-align: justify;\">Surat pernyataan pengelolaan air limbah di atas materai 6000.</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Dokumen UKL-UPL.</li>\r\n	<li style=\"text-align: justify;\">Surat perjanjian kerjasama rujukan dengan Rumah Sakit bagi klinik rawat jalan dan 24 jam.</li>\r\n	<li style=\"text-align: justify;\">Surat perjanjian pengelolaan sampah medis dengan pihak ketiga (bila tidak mempunyai sarana pengelolaan sendiri).</li>\r\n	<li style=\"text-align: justify;\">Profil klinik yang meliputi:\r\n	<ul>\r\n		<li>Struktur organisasi kepengurusan</li>\r\n		<li>Daftar tenaga medis (melampirkan SIP, STR, dan Ijazah)</li>\r\n		<li>Tenaga kesehatan (melampirkan SIK, STR, dan Ijazah)</li>\r\n		<li>Tenaga non kesehatan (melampirkan Ijazah)</li>\r\n		<li>Daftar sarana dan prasarana penunjang (ambulans, pemadam kebakaran, dll)</li>\r\n		<li>Daftar peralatan medis dan non medis</li>\r\n		<li>Daftar tarif.</li>\r\n	</ul>\r\n	</li>\r\n	<li style=\"text-align: justify;\">Surat pengantar dari kepala Puskesmas setempat.</li>\r\n	<li style=\"text-align: justify;\">Data dokter penanggungjawab dengan dilengkapi dengan:\r\n	<ul>\r\n		<li>Fotokopi KTP</li>\r\n		<li>Fotokopi SIP dokter penanggungjawab</li>\r\n		<li>Surat keterangan tidak keberatan dari atasan langsung</li>\r\n		<li>Surat penunjukan sebagai penanggung jawab klinik</li>\r\n		<li>Surat pernyataan sanggup melaksanakan kegiatan pelayanan sesuai dengan peraturan perundang-undangan yang berlaku</li>\r\n		<li>Surat pernyataan kesanggupan sebagai penangung jawab klinik</li>\r\n	</ul>\r\n	</li>\r\n	<li style=\"text-align: justify;\">Standard Operating Procedure (SOP).</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan penggunaan penerangan.</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan penggunaan air.</li>\r\n	<li style=\"text-align: justify;\">Mengembalikan surat izin yang lama (untuk perpanjangan, pindah alamat, atau ganti penanggungjawab).</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:45:52', NULL),
(36, 'd8af1932-a9ae-4bac-b800-6ac4d4cd0953', 'P032', 'Izin SIA', 'Izin SIA', '<p style=\"text-align:justify\"><strong>Izin SIA</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Fotokopi KTP Apoteker Penanggungjawab atau keterangan domisili dari Camat setempat bagi yang memiliki KTP di luar Pangkalpinang</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Surat Izin Praktek Apoteker (SIPA) Penanggungjawab</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Surat Izin Praktek Apoteker (SIPA) Pendamping</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Surat Izin Praktik Tenaga Teknis Kefarmasian</li>\r\n	<li style=\"text-align: justify;\">Pas Photo Apoteker Penanggungjawab berwarna latar belakang merah ukuran 4x6 cm sebanyak 2 lembar</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Akte kerjasama Apoteker Penanggung jawab Apotek dengan Pemilik Sarana Apotek (PSA) dari Notaris</li>\r\n	<li style=\"text-align: justify;\">Gambar Denah Bangunan dan Denah Alamat Tempat Usaha</li>\r\n	<li style=\"text-align: justify;\">Daftar terperinci alat kelengkapan Apotek</li>\r\n	<li style=\"text-align: justify;\">Surat pernyataan dari Apoteker Penanggungjawab Apotek bahwa tidak bekerja tetap pada perusahaan farmasi lain dan tidak menjadi Apoteker Penanggungjawab di Apotek lain (bermaterai)</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan dari Apotek Penanggungjawab Apotek akan mentaati dan melaksanakan Pekerjaan Kefarmasian sesuai perundangan dan peraturan dibidang kefarmasian yang berlaku (bermaterai)</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan dari Apoteker Penanggungjawab Apotek akan berada di tempat pada saat jam buka Apotek , dan apabila berhalangan akan digantikan oleh Apoteker Pendamping (bermaterai)</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan Pemilik Sarana tidak terlibat pelanggaran perundang-undangan dibidang obat (bermaterai)</li>\r\n	<li style=\"text-align: justify;\">Berita Acara Serah terima tanggung jawab APA dan surat pengunduran diri APA lama ( jika terjadi pergantian APA )</li>\r\n	<li style=\"text-align: justify;\">Fotokopi Izin Mendirikan Bangunan (IMB)</li>\r\n	<li style=\"text-align: justify;\">Mengembalikan surat izin yang lama (untuk perpanjangan, pindah alamat atau ganti penanggungjawab)</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:27:31', NULL),
(37, '6e484352-2d63-45de-96e6-fbeea160f0bd', 'P033', 'Izin SIPTW', 'Izin SIPTW', '<p><strong>Izin SIPTW</strong></p>\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n<ol>\r\n    <li>Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang memiliki KTP di Luar Pangkalpinang</li>\r\n    <li>Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n    <li>Fotocopy Ijazah yang Dilegalisir</li>\r\n    <li>Fotocopy STR Praktik Terapis Wicara yang Dilegalisir</li>\r\n    <li>Rekomendasi Dari Organisasi Profesi</li>\r\n    <li>Surat Keterangan Sehat dari Dokter atau Puskesmas</li>\r\n    <li>Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai)</li>\r\n    <li>Fotocopy SIG</li>\r\n    <li>Pengambilan Surat Iain Yang Lama (Perpanjangan)</li>\r\n</ol>\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:35:59', NULL),
(38, '4ab06e60-b0ec-470d-9472-15f39ea4a85b', 'P034', 'Izin SIPTTK', 'Izin SIPTTK', '<p><strong>Izin SIPTTK</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang memiliki KTP di Luar Pangkalpinang</li>\r\n	<li>Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n	<li>Fotocopy Ijazah yang Dilegalisir</li>\r\n	<li>Fotocopy STR Tenaga Teknis Kefarmasian yang Dilegalisir</li>\r\n	<li>Rekomendasi Dari Organisasi Profesi</li>\r\n	<li>Surat Keterangan Sehat dari Dokter atau Puskesmas</li>\r\n	<li>Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai)</li>\r\n	<li>Fotocopy SIG</li>\r\n	<li>Pengambilan Surat Iain Yang Lama (Perpanjangan)</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:35:26', NULL);
