(43, '1fa9ac32-7e22-41df-8721-b3fe50abbad5', 'P039', 'Izin SIPOT', 'Izin SIPOT', '<p style=\"text-align:justify\"><strong>Izin SIPOT</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang memiliki KTP di Luar Pangkalpinang</li>\r\n	<li style=\"text-align: justify;\">Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n	<li style=\"text-align: justify;\">Fotocopy Ijazah yang Dilegalisir</li>\r\n	<li style=\"text-align: justify;\">Fotocopy STR Okupasi Terapis yang Dilegalisir</li>\r\n	<li style=\"text-align: justify;\">Rekomendasi Dari Organisasi Profesi</li>\r\n	<li style=\"text-align: justify;\">Surat Keterangan Sehat dari Dokter atau Puskesmas</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan Dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai)</li>\r\n	<li style=\"text-align: justify;\">Fotocopy SIG</li>\r\n	<li style=\"text-align: justify;\">Pengambilan Surat Iain Yang Lama (Perpanjangan)</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 06:31:12', NULL),
