(58, 'efc2e965-1a9b-49f0-8cb6-4e49b4a0594d', 'P054', 'Izin SIKOT', 'Izin SIKOT', '<p><strong>Izin SIKOT</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang memiliki KTP di Luar Pangkalpinang</li>\r\n	<li>Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n	<li>Fotocopy Ijazah yang Dilegalisir</li>\r\n	<li>Fotocopy STR Kerja Okupasi Terapis yang Dilegalisir</li>\r\n	<li>Rekomendasi Dari Organisasi Profesi</li>\r\n	<li>Surat Keterangan Sehat dari Dokter atau Puskesmas</li>\r\n	<li>Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan Dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai)</li>\r\n	<li>Fotocopy SIG</li>\r\n	<li>Pengambilan Surat Iain Yang Lama (Perpanjangan)</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:30:32', NULL),
(59, '443d8fb7-8a1d-4323-ad8f-8a804898c3a6', 'P055', 'Izin SIKF', 'Izin SIKF', '<p><strong>Izin SIKF</strong></p>\r\n\r\n<p><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li>Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang memiliki KTP di Luar Pangkalpinang</li>\r\n	<li>Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n	<li>Fotocopy Ijazah yang Dilegalisir</li>\r\n	<li>Fotocopy STR Kerja Fisiotrapis yang Dilegalisir</li>\r\n	<li>Rekomendasi Dari Organisasi Profesi</li>\r\n	<li>Surat Keterangan Sehat dari Dokter atau Puskesmas</li>\r\n	<li>Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan Dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai)</li>\r\n	<li>Fotocopy SIG</li>\r\n	<li>Pengambilan Surat Iain Yang Lama (Perpanjangan)</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:28:36', NULL),
(60, '03992636-18ab-49a6-9b6b-91f4e9e70499', 'P056', 'Izin SIKB', 'Izin SIKB', '<p style=\"text-align:justify\"><strong>Izin SIKB</strong></p>\r\n\r\n<p style=\"text-align:justify\"><em>Persyaratan Administrasi :</em></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang Memiliki KTP di Luar Pangkalpinang</li>\r\n	<li style=\"text-align: justify;\">Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n	<li style=\"text-align: justify;\">Fotocopy Ijazah yang Dilegalisir</li>\r\n	<li style=\"text-align: justify;\">Fotocopy STR Kerja Bidan yang Dilegalisir</li>\r\n	<li style=\"text-align: justify;\">Rekomendasi Dari Organisasi Profesi</li>\r\n	<li style=\"text-align: justify;\">Surat Keterangan Sehat dari Dokter atau Puskesmas</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan Dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai)</li>\r\n	<li style=\"text-align: justify;\">Fotocopy SIG</li>\r\n	<li style=\"text-align: justify;\">Pengambilan Surat Iain Yang Lama (Perpanjangan)</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 05:28:03', NULL),
(61, '520a578f-5310-4937-9ec9-0146d6b7e861', 'P057', 'Izin Fisikawan Prostetik', 'Izin Fisikawan Prostetik', '<p><strong>Izin Fisikawan Prostetik</strong></p>\r\n\r\n<p><strong>Persyaratan Administrasi:</strong></p>\r\n\r\n<ol>\r\n	<li>Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang Memiliki KTP di Luar Pangkalpinang.</li>\r\n	<li>Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar.</li>\r\n	<li>Fotocopy Ijazah yang Dilegalisir.</li>\r\n	<li>Fotocopy STR Fisikawan Prostetik yang Dilegalisir.</li>\r\n	<li>Rekomendasi Dari Organisasi Profesi.</li>\r\n	<li>Surat Keterangan Sehat dari Dokter atau Puskesmas.</li>\r\n	<li>Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan Dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai).</li>\r\n	<li>Fotocopy SIG.</li>\r\n	<li>Pengambilan Surat Iain Yang Lama (Perpanjangan).</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:44:14', NULL),
(62, 'd2983455-89b9-42a8-b99e-f51aad8cc6b2', 'P058', 'Izin Akupuntur', 'Izin Akupuntur', '<p><strong>Izin Akupuntur</strong></p>\r\n<p><strong>Persyaratan Administrasi :</strong></p>\r\n<ol>\r\n    <li>Fotocopy KTP Pemohon atau Keterangan Domisili dari Camat Setempat Bagi Pemohon yang Memiliki KTP diluar Pangkalpinang.</li>\r\n    <li>Pas Photo Terbaru Berwarna Latar Belakang Merah Ukuran 3x4 cm sebanyak 4 (empat) lembar.</li>\r\n    <li>Fotocopy Ijazah yang Dilegalisir.</li>\r\n    <li>Fotocopy STR Akupuntur yang Dilegalisir.</li>\r\n    <li>Rekomendasi Dari Organisasi Profesi.</li>\r\n    <li>Surat Keterangan Sehat dari Dokter atau Puskesmas.</li>\r\n    <li>Surat Pernyataan Memiliki Tempat Kerja Profesi atau Surat Keterangan Dari Pimpinan Fasilitas Pelayanan Sebagai Tempat Kerjanya (bermaterai).</li>\r\n    <li>Fotocopy SIG.</li>\r\n    <li>Pengambilan Surat Iain Yang Lama (Perpanjangan).</li>\r\n</ol>\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 94, '2023-09-11 03:43:21', NULL),
(63, 'dd6f9769-d838-482c-b017-94e8eec4f5c2', 'P059', 'INFO PERIZINAN', 'INFO PERIZINAN', '<h4 style=\"text-align:justify\">INFO PERIZINAN</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>Izin Akupuntur</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Fisikawan Prostetik</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKB (Surat Izin Kerja Bidan)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKF (Surat Izin Kerja Fisiotrapis)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKOT (Surat Izin Kerja Okupasi Terapis)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKP (Surat Izin Kerja Perawat)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKPM (Surat Izin Kerja Perekam Medis)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKR (Surat Izin Kerja Radiografer)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKRO (Surat izin kerja Refraksionis Optisien)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKTG (Surat Izin Kerja Tenaga Teknisi Gizi)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKTGz (Surat Izin Kerja Tenaga Gizi)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKTS (Surat Izin Kerja Tenaga Sanitarian)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKTTE (Surat Izin Kerja Tenaga Tehnik Elektromedik)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIKTW (Surat Izin Kerja Trapis Wicara)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIP (Surat izin Praktik Dokter/Dokter Gigi (SIP))</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPA (Surat izin Praktik Dokter/Dokter Gigi (SIP))</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIP &ndash; ATLM (Surat Izin Praktik Ahli Teknologi Laboratorium Medik)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPB (Surat Izin Praktik Bidan)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPF (Surat Izin Praktik Fisiotrapis)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPOT (Surat Izin Praktik Okupasi Terapis)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPP (Surat Izin Praktik Perawat)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPPA (Surat Izin Praktik Penata Anestesi)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPTGM (Surat Izin Praktik Terapis Gigi dan Mulut)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPTGZ (Klasifikasi/Sasaran SIPTGz)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPTTK (Surat Izin Praktik Tenaga Teknis Kefarmasian)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIPTW (Surat Izin Praktik Trapis Wicara)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin SIA (Surat Izin Apotek)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Klinik</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Laboratorium Klinik</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Mendirikan Rumah Sakit</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Operasional Rumah Sakit</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Optik</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Puskesmas</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Radiologi</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin STPT (Surat Terdaftar Penyehat Tradisional)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Toko Alat Kesehatan</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Toko Obat</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Tukang Gigi</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Umot (Usaha Mikro Obat Tradisional)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>IMB (Izin Mendirikan Bangunan)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>IPPL (Izin Peruntukan Penggunaan Lahan)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Lokasi</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Usaha Jasa Konstruksi</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Gangguan</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Prinsip PM (Penanaman Modal)</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Izin Perluasan PM</strong></li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\">Terima Kasih.</p>\r\n', NULL, NULL, 94, '2023-09-11 03:31:57', NULL),
(64, 'c73bfddc-a92c-4508-a178-1daef651b4cb', 'P060', 'INFO PENCATATAN SIPIL', 'INFO PENCATATAN SIPIL', '<h4 style=\"text-align:justify\">PENCATATAN SIPIL</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>INFO AKTA KELAHIRAN</strong>: Untuk mengetahui informasi terkait pembuatan Akta Kelahiran.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO AKTA PERKAWINAN</strong>: Untuk mengetahui informasi terkait pencatatan dan penerbitan kutipan Akta Perkawinan.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO AKTA PERCERAIAN</strong>: Untuk mengetahui informasi terkait pencatatan dan penerbitan Akta Perceraian.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO AKTA KEMATIAN</strong>: Untuk mengetahui informasi terkait pencatatan dan penerbitan Akta Kematian.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO PPA</strong>: Untuk mengetahui informasi terkait pencatatan dan penerbitan Akta Pengesahan Anak dan Pengakuan Anak.</li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:27:44', NULL),
(65, 'f2ddba15-34e0-4e97-be6b-22adc18f4f12', 'P061', 'INFO PENDAFTARAN PENDUDUK', 'INFO PENDAFTARAN PENDUDUK', '<h4 style=\"text-align:justify\">PENDAFTARAN PENDUDUK</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>INFO KTP</strong>: Untuk mengetahui informasi terkait pembuatan KTP.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO KK</strong>: Untuk mengetahui informasi terkait pembuatan KK.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO KIA</strong>: Untuk mengetahui informasi terkait KIA.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO BIODATA</strong>: Untuk mengetahui pencatatan biodata WNI dan WNA.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO PINDAH WNI</strong>: Untuk mengetahui informasi terkait kepindahan WNI.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO SKTT WNA</strong>: Untuk mengetahui informasi terkait tempat tinggal untuk WNA.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO PENDUDUK</strong>: Untuk mengetahui informasi terkait pendataan penduduk non permanen.</li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:28:30', NULL),
(66, '417df2f1-15f3-4bdd-ae08-51897288c03f', 'P062', 'INFO KEPENDUDUKAN', 'INFO KEPENDUDUKAN', '<h4 style=\"text-align:justify\">INFO KEPENDUDUKAN</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>INFO PENDAFTARAN PENDUDUK</strong>: Untuk mengetahui informasi terkait pembuatan KTP, KK, KIA, Pencatatan biodata WNI dan WNA, Kepindahan WNI, Surat Keterangan Tempat Tinggal untuk WNA dan Pendataan Penduduk Non Permanen.</li>\r\n	<li style=\"text-align: justify;\"><strong>INFO PENCATATAN SIPIL</strong>: Untuk mengetahui informasi terkait Pembuatan dan Pencatatan Akta Kelahiran, Perkawinan, Perceraian, Kematian, Pengesahan Anak dan Pengakuan Anak.</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\">Informasi lebih detil silahkan akses Website : <a href=\"https://disdukcapil.pangkalpinangkota.go.id\">https://disdukcapil.pangkalpinangkota.go.id</a></p>\r\n\r\n<p style=\"text-align:justify\"><em>Terima Kasih</em></p>\r\n', NULL, NULL, 34, '2023-09-11 03:19:49', NULL),
(67, '5b158032-64f7-431a-87f5-a8e901f9d6dc', 'P063', 'INFO PPA', 'INFO PPA', '<h4 style=\"text-align:justify\">PENCATATAN AKTA PENGESAHAN ANAK DAN PENGAKUAN ANAK</h4>\r\n\r\n<h5 style=\"text-align:justify\">Penerbitan Akta Pengesahan Anak harus memenuhi persyaratan:</h5>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Pemohon mengisi form. F2.01</li>\r\n	<li style=\"text-align: justify;\">Surat pengantar dari RT/RW dan diketahui kepala desa/lurah</li>\r\n	<li style=\"text-align: justify;\">Kutipan akta kelahiran</li>\r\n	<li style=\"text-align: justify;\">Fotocopy kutipan akta perkawinan</li>\r\n	<li style=\"text-align: justify;\">Fotocopy KK</li>\r\n	<li style=\"text-align: justify;\">Fotocopy KTP pemohon</li>\r\n	<li style=\"text-align: justify;\">Surat Pernyataan bermaterai yang menyatakan bahwa anak tersebut anak biologis suami istri bagi yang non-Muslim</li>\r\n	<li style=\"text-align: justify;\">Bagi yang Muslim melalui penetapan Pengadilan Agama</li>\r\n</ol>\r\n\r\n<h5 style=\"text-align:justify\">Pencatatan pengesahan anak bagi Penduduk Orang Asing di wilayah Negara Kesatuan Republik Indonesia harus memenuhi persyaratan:</h5>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Kutipan akta kelahiran</li>\r\n	<li style=\"text-align: justify;\">Kutipan akta perkawinan yang menerangkan terjadinya peristiwa perkawinan agama atau kepercayaan terhadap Tuhan Yang Maha Esa terjadi sebelum kelahiran anak</li>\r\n	<li style=\"text-align: justify;\">KK orang tua</li>\r\n	<li style=\"text-align: justify;\">Dokumen Perjalanan bagi ayah atau ibu Orang Asing</li>\r\n</ol>\r\n\r\n<h5 style=\"text-align:justify\">Penerbitan Akta Pengakuan Anak harus memenuhi persyaratan:</h5>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Surat pengantar dari RT/RW dan diketahui kepala desa/lurah</li>\r\n	<li style=\"text-align: justify;\">Surat Pengakuan anak dari ayah biologis yang disetujui ibu kandung bagi non-Muslim</li>\r\n	<li style=\"text-align: justify;\">Surat Keterangan telah terjadinya perkawinan dari pemuka agama atau penghayat kepercayaan terhadap Tuhan Yang Maha Esa.</li>\r\n	<li style=\"text-align: justify;\">Kutipan akta kelahiran</li>\r\n	<li style=\"text-align: justify;\">Fotocopy KK dan KTP ayah biologis, ibu kandung.</li>\r\n	<li style=\"text-align: justify;\">Penetapan Pengadilan Agama bagi yang Muslim</li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:33:41', NULL),
(68, '4cfe49d9-ac6a-41d6-b8b3-9e34677e3423', 'P064', 'INFO AKTA KEMATIAN', 'AKTA KEMATIAN', '<p style=\"text-align:center\"><strong>PENCATATAN AKTA KEMATIAN</strong></p>\r\n\r\n<p>Penerbitan Akta, memenuhi persyaratan :</p>\r\n\r\n<ol>\r\n	<li>Pemohon mengisi form F2.01</li>\r\n	<li>Surat keterangan kematian dari dokter/paramedic bagi yang meninggal di RS</li>\r\n	<li>Surat keterangan kematian dari Lurah/Kepala desa jika meninggal dirumah</li>\r\n	<li>Fotocopy Akta kelahiran yang meninggal bagi yang memiliki akta</li>\r\n	<li>Asli KTP dan KK</li>\r\n	<li>Fotocopy dokumen imigrasi bagi orang asing</li>\r\n	<li>Fotocopy KTP saksi minimal 1 (satu)</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Orang Pencatatan kematian WNI di luar wilayah Negara Kesatuan Republik Indonesia yang dilakukan pada instansi yang berwenang di negara setempat wajib dilaporkan kepada Perwakilan Republik Indonesia dengan memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li>Kutipan akta kematian/bukti pencatatan kematian dari negara setempat;</li>\r\n	<li>Dokumen Perjalanan Republik Indonesia; dan</li>\r\n	<li>Surat keterangan yang menunjukkan domisili atau surat keterangan pindah luar negeri</li>\r\n</ol>\r\n\r\n<p>Dalam hal negara setempat tidak menyelenggarakan pencatatan kematian bagi Orang Asing, pencatatan kematian WNI dilaksanakan pada Perwakilan Republik Indonesia dengan memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li>Surat keterangan kematian dari instansi yang berwenang di negara setempat;</li>\r\n	<li>Dokumen Perjalanan Republik Indonesia; dan</li>\r\n	<li>Surat keterangan yang menunjukkan domisili atau surat keterangan pindah luar negeri.</li>\r\n</ol>\r\n', NULL, NULL, 34, '2022-04-04 04:32:42', NULL),
(69, '7c27b4b4-36f7-4385-8d8a-11d4819a476d', 'P065', 'INFO AKTA PERCERAIAN', 'AKTA PERCERAIAN', '<p style=\"text-align:center\"><strong>PENCATATAN AKTA PERCERAIAN</strong></p>\r\n\r\n<p>Penerbitan Akta Perceraian harus memenuhi persyaratan :</p>\r\n\r\n<ol>\r\n	<li>Pemohon mengisi form F2.01</li>\r\n	<li>Salinan putusan pengadilan yang telah memperoleh kekuatan hukum tetap</li>\r\n	<li>Kutipan akta perkawinan suami dan isteri (asli) (Jika kutipan asli tidak bisa diberikan, pemohon harus membuat surat pernyataan)</li>\r\n	<li>Fotocopy KTP dan Kartu Keluarga</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Perceraian WNI di luar wilayah Negara Kesatuan Republik Indonesia yang dilakukan pada instansi yang berwenang di negara setempat wajib dilaporkan kepada Perwakilan Republik Indonesia dengan memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li>Kutipan akta perceraian/bukti pencatatan perceraian dari negara setempat;</li>\r\n	<li>Dokumen Perjalanan Republik Indonesia; dan</li>\r\n	<li>Surat keterangan yang menunjukkan domisili atau surat keterangan pindah luar negeri.</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Dalam hal negara setempat tidak menyelenggarakan pencatatan perceraian bagi Orang Asing, pencatatan perceraian WNI dilakukan pada Perwakilan Republik Indonesia dengan memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li>Dokumen yang sah tentang terjadinya perceraian di negara setempat;</li>\r\n	<li>Kutipan akta perkawinan atau bukti pencatatan perkawinan; dan</li>\r\n	<li>Dokumen Perjalanan Republik Indonesia atau surat keterangan pindah luar negeri suami dan istri yang telah bercerai.</li>\r\n</ol>\r\n\r\n<p>Jika pemohon tidak dapat menyerahkan kutipan akta perkawinan atau bukti pencatatan perkawinan, pemohon membuat surat pernyataan yang menyatakan kutipan akta perkawinan tidak dimiliki dengan alasan sesuai dengan ketentuan peraturan perundang-undangan.</p>\r\n', NULL, NULL, 34, '2022-04-04 04:37:45', NULL),
(70, '152b5162-b42c-4e40-a933-b420e574b6df', 'P066', 'INFO AKTA PERKAWINAN', 'Data Info Akta Perkawinan', '<h4 style=\"text-align:justify\">PENCATATAN DAN PENERBITAN KUTIPAN AKTA PERKAWINAN</h4>\r\n\r\n<p style=\"text-align:justify\"><strong>Pencatatan perkawinan Penduduk WNI di Wilayah Negara Kesatuan Republik Indonesia</strong> harus memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Pemohon mengisi form. F2.01</li>\r\n	<li style=\"text-align: justify;\">Fotocopy surat bukti perkawinan agama/surat perkawinan penghayat kepercayaan yang ditandatangani oleh pemuka penghayat kepercayaan (dilegalisir)</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan dari Lurah</li>\r\n	<li style=\"text-align: justify;\">Fotocopy Kartu Keluarga</li>\r\n	<li style=\"text-align: justify;\">Fotocopy KTP Suami dan Isteri, serta saksi</li>\r\n	<li style=\"text-align: justify;\">Fotocopy Akta Kelahiran suami dan isteri</li>\r\n	<li style=\"text-align: justify;\">2 (dua) orang saksi yang telah berusia 21 tahun keatas harus hadir</li>\r\n	<li style=\"text-align: justify;\">Akta Kelahiran Anak yang diakui</li>\r\n	<li style=\"text-align: justify;\">Akta Perceraian/Kematian jika yang bersangkutan telah pernah kawin</li>\r\n	<li style=\"text-align: justify;\">Pas Photo suami dan istri berdampingan ukuran 4 x 6 cm, sebanyak = 5 lembar</li>\r\n	<li style=\"text-align: justify;\">Izin dari komandan bagi anggota TNI/Polri</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><strong>Pencatatan perkawinan Orang Asing di Wilayah Negara Kesatuan Republik Indonesia</strong> harus memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Surat keterangan telah terjadinya perkawinan dari pemuka agama atau penghayat kepercayaan terhadap Tuhan Yang Maha Esa;</li>\r\n	<li style=\"text-align: justify;\">Pas foto berwarna suami dan isteri;</li>\r\n	<li style=\"text-align: justify;\">Dokumen Perjalanan;</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan tempat tinggal bagi pemegang izin tinggal terbatas;</li>\r\n	<li style=\"text-align: justify;\">KK;</li>\r\n	<li style=\"text-align: justify;\">KTP-eL; dan</li>\r\n	<li style=\"text-align: justify;\">Izin dari negara atau perwakilan negaranya</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><strong>Perkawinan WNI di luar wilayah Negara Kesatuan Republik Indonesia wajib dilaporkan kepada Perwakilan Republik Indonesia setelah dicatatkan pada instansi yang berwenang di negara setempat</strong> dengan memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Kutipan akta perkawinan dari negara setempat; dan</li>\r\n	<li style=\"text-align: justify;\">Dokumen Perjalanan Republik Indonesia suami dan istri.</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><strong>Jika negara setempat tidak menyelenggarakan pencatatan perkawinan bagi Orang Asing, pencatatan perkawinan WNI dilakukan pada Perwakilan Republik Indonesia</strong> dengan memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Surat keterangan telah terjadinya perkawinan dari pemuka agama atau penghayat kepercayaan terhadap Tuhan Yang Maha Esa;</li>\r\n	<li style=\"text-align: justify;\">Dokumen Perjalanan Republik Indonesia suami dan istri.</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><strong>Perkawinan WNI di luar wilayah Negara Kesatuan Republik Indonesia wajib dilaporkan ke Disdukcapil KabupatenlKota atau UPT Disdukcapil Kabupaten/Kota di tempat Penduduk berdomisili dengan memenuhi persyaratan :</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Bukti pelaporan perkawinan dari Perwakilan Republik Indonesia; dan</li>\r\n	<li style=\"text-align: justify;\">Kutipan akta perkawinan.</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><strong>Perkawinan WNI dengan Orang Asing di luar wilayah Negara Kesatuan Republik Indonesia yang dilakukan pada instansi yang berwenang di negara setempat wajib dilaporkan kepada Perwakilan Republik Indonesia dengan memenuhi persyaratan :</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Kutipan akta perkawinan/bukti pencatatan perkawinan dari negara setempat;</li>\r\n	<li style=\"text-align: justify;\">Dokumen Perjalanan Republik Indonesia dan Dokumen Perjalanan; dan</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan yang menunjukkan domisili atau surat keterangan pindah luar negeri.</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\"><strong>Dalam hal negara setempat tidak menyelenggarakan pencatatan perkawinan bagi Orang Asing, pencatatan perkawinan WNI dengan Orang Asing dilaksanakan pada Perwakilan Republik Indonesia dengan memenuhi persyaratan :</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Surat keterangan terjadinya perkawinan di negara setempat;</li>\r\n	<li style=\"text-align: justify;\">Pas foto berwarna suami dan isteri;</li>\r\n	<li style=\"text-align: justify;\">Dokumen Perjalanan Republik Indonesia dan Dokumen Perjalanan; dan</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan yang menunjukkan domisili atau surat keterangan pindah luar negeri.</li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:19:11', NULL),
(71, '77c3b2d8-c110-4a10-abce-ac01f257577d', 'P067', 'INFO AKTA KELAHIRAN', 'INFO AKTA KELAHIRAN', '<p>INFO AKTA KELAHIRAN</p>\r\n\r\n<p>PENCATATAN DAN PENERBITAN KUTIPAN AKTA KELAHIRAN &gt; 60 HARI</p>\r\n\r\n<p>Pencatatan kelahiran WNI harus memenuhi persyaratan :</p>\r\n\r\n<ol>\r\n	<li>Pemohon mengisi form F2.01</li>\r\n	<li>Surat keterangan kelahiran dari Dokter/Bidan/penolong kelahiran (Penduduk dapat membuat surat pernyataan tanggung jawab mutlak atas kebenaran data kelahiran dengan diketahui oleh 2(dua) orang saksi dalam hal: tidak memiliki surat keterangan kelahiran</li>\r\n	<li>Nama dan identitas saksi kelahiran (2 orang saksi dengan melampirkan fotocopy KTP)</li>\r\n	<li>Fotocopy Kartu Keluarga</li>\r\n	<li>Fotocopy KTP orang tua</li>\r\n	<li>Fotocopy Akta Nikah/Akta Perkawinan orang tua(tidak memiliki buku nikah/kutipan akta perkawinan atau bukti lain yang sah tetapi status hubungan dalam KK menunjukan sebagai suami istri,Penduduk dapat membuat surat pernyataan tanggung jawab mutlak atas kebenaran data pasangan suami istri dengan diketahui oleh 2 (dua) orang saksi</li>\r\n	<li>Para pihak harus hadir menandatangani buku register Pencatatan kelahiran WNI bagi anak yang baru lahir atau baru ditemukan dan tidak diketahui asal usulnya atau keberadaan orang tuanya* Harus memenuhi persyaratan berita acara dari kepolisian. *Pencatatan kelahiran WNI bagi anak yang tidak diketahui asal usulnya atau keberadaan orang tuanya selain yang dimaksud pada point c harus memenuhi persyaratan* Surat pernyataan tanggung jawab mutlak kebenaran data kelahiran dengan 2 (dua) orang saksi.</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Pencatatan kelahiran WNI yang bertempat tinggal di luar wilayah Negara Kesatuan Republik Indonesia yang sedang berkunjung ke Indonesia harus memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li>Surat keterangan kelahiran;</li>\r\n	<li>Buku nikah/kutipan akta perkawinan atau bukti</li>\r\n	<li>nikah/perkawinan lainnya; dan</li>\r\n	<li>Dokumen Perjalanan Republik Indonesia dan/atau</li>\r\n	<li>Dokumen Perjalanan orang tua; atau</li>\r\n	<li>Surat keterangan pindah luar negeri.</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Pencatatan kelahiran Orang Asing pemegang izin kunjungan, pemegang izin tinggal terbatas dan pemegangizin tinggal tetap harus memenuhi persyaratan:</p>\r\n\r\n<ol>\r\n	<li>Surat keterangan kelahiran;</li>\r\n	<li>Dokumen Perjalanan; dan</li>\r\n	<li>KTP-el atau kartu izin tinggal tetap atau kartu izin tinggal terbatas atau visa kunjungan.</li>\r\n</ol>\r\n', NULL, NULL, 34, '2022-04-04 04:29:28', NULL);
INSERT INTO `pelayanan_publik` (`id`, `uid`, `kode`, `keyword`, `keterangan`, `response`, `file`, `mimes`, `id_opd`, `updated_at`, `created_at`) VALUES
(72, 'fe8512f0-26e0-49a1-954d-38838a5efdb5', 'P068', 'INFO PENDUDUK', 'INFO PENDUDUK', '<h4 style=\"text-align:justify\">Pendataan Penduduk Non Permanen</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F 4.01 penduduk non permanen</li>\r\n	<li style=\"text-align: justify;\">Surat pengantar dari RT/RW</li>\r\n	<li style=\"text-align: justify;\">Surat pengantar dari Lurah</li>\r\n	<li style=\"text-align: justify;\">KTP-el</li>\r\n	<li style=\"text-align: justify;\">Kartu keluarga</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan dari penjamin</li>\r\n	<li style=\"text-align: justify;\">Pas photo berwarna 2x3 sebanyak 2 lembar</li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:29:38', NULL),
(73, 'd90cffd2-4873-4065-a720-22a73593c9e5', 'P069', 'INFO SKTT WNA', 'INFO SKTT WNA', '<h4 style=\"text-align:justify\">Surat Keterangan Tempat Tinggal (SKTT) untuk WNA</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.03</li>\r\n	<li style=\"text-align: justify;\">Dokumen Perjalanan</li>\r\n	<li style=\"text-align: justify;\">KITAS</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan dari sponsor</li>\r\n	<li style=\"text-align: justify;\">Surat Tanda Melapor (STM) dari kepolisian</li>\r\n	<li style=\"text-align: justify;\">Pas photo berwarna 2x3 sebanyak 2 lembar</li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:36:01', NULL),
(74, '8d6c9373-8d9b-4812-a96c-13bbb4d64a0f', 'P070', 'INFO PINDAH WNI', 'INFO PINDAH WNI', '<h4 style=\"text-align:justify\">SURAT KETERANGAN PINDAH WNI</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>Pengisian formulir F1.03</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Foto Copy KTP-el</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Kartu Keluarga (KK) asli/foto copy</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>Akta perceraian atau Formulir F1.05</strong></li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:32:34', NULL),
(75, '36fe6942-15f6-4235-868c-c1266bae44e5', 'P071', 'INFO BIODATA', 'INFO BIODATA', '<h4 style=\"text-align:justify\">BIODATA WNI dan WNA</h4>\r\n\r\n<h5 style=\"text-align:justify\">A. Pencatatan biodata penduduk WNI di wilayah Negara Kesatuan Republik Indonesia</h5>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.01</li>\r\n	<li style=\"text-align: justify;\">Surat pengantar dari rukun tetangga dan rukun warga atau yang disebut dengan nama lain</li>\r\n	<li style=\"text-align: justify;\">Foto copy salah satu dokumen atau bukti peristiwa kependudukan dan peristiwa penting, seperti buku nikah, kutipan akta perceraian, dan atau kutipan akta pencatatan sipil terkait lainnya</li>\r\n	<li style=\"text-align: justify;\">Foto copy ijazah terakhir</li>\r\n	<li style=\"text-align: justify;\">Formulir F1.04 (surat pernyataan tidak memiliki dokumen kependudukan) bila diperlukan</li>\r\n	<li style=\"text-align: justify;\">Formulir F1.5 (surat pernyataan tanggung jawab mutlak perkawinan/perceraian belum tercatat) bila diperlukan</li>\r\n	<li style=\"text-align: justify;\">Formulir F1.07 (Surat kuasa dalam pelayanan administrasi kependudukan) bila diperlukan</li>\r\n</ol>\r\n\r\n<h5 style=\"text-align:justify\">B. Pencatatan biodata penduduk WNI yang datang dari luar wilayah NKRI karena pindah</h5>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.01</li>\r\n	<li style=\"text-align: justify;\">Surat pengantar dari rukun tetangga dan rukun warga atau yang disebut dengan nama lain</li>\r\n	<li style=\"text-align: justify;\">Foto copy salah satu dokumen atau bukti peristiwa kependudukan dan peristiwa penting, seperti buku nikah, kutipan akta perceraian, dan atau kutipan akta pencatatan sipil terkait lainnya</li>\r\n	<li style=\"text-align: justify;\">Foto copy ijazah terakhir</li>\r\n	<li style=\"text-align: justify;\">Dokumen perjalanan republik Indonesia</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan pindah dari Perwakilan Republik Indonesia</li>\r\n</ol>\r\n\r\n<h5 style=\"text-align:justify\">C. Pencatatan biodata Orang Asing yang memiliki izin tinggal terbatas dan Orang Asing yang memiliki izin tinggal tetap</h5>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.01</li>\r\n	<li style=\"text-align: justify;\">Foto copy dokumen perjalanan</li>\r\n	<li style=\"text-align: justify;\">Foto copy kartu izin tinggal terbatas atau izin tinggal tetap</li>\r\n</ol>\r\n', NULL, NULL, 34, '2023-09-11 03:19:21', NULL),
(76, 'cae8d19d-9546-4d86-809c-66cc62b49af7', 'P072', 'SENYUM', 'SENYUM', '<p><strong>Pangkalpinang Kota Beribu Senyuman</strong></p>\r\n\r\n<p>Silahkan ketik keyword yang bertulis tebal dibawah ini :</p>\r\n\r\n<ol>\r\n	<li><strong>INFO COVID</strong>: Untuk mengetahui Informasi terkait Covid-19 di Kota Pangkalpinang setiap harinya.</li>\r\n	<li><strong>INFO KEPENDUDUKAN</strong>: Untuk mengetahui informasi terkait Pendaftaran Penduduk dan Pencatatan Sipil.</li>\r\n	<li><strong>INFO PERIZINAN</strong>: Untuk mengetahui informasi pelayanan perizinan penanaman modal, bidang lingkungan, perdagangan, perindustrian, konstruksi, penataan ruang, kesehatan dan ketenagakerjaan serta pemberian layanan atas semua bentuk pelayanan perizinan dan non perizinan yang menjadi kewenangan kota yang mengacu pada prinsip koordinasi, integrasi, sinkronisasi dan keamanan berkas yang meliputi pemberian, penolakan, pengeluaran dan pencabutan izin.</li>\r\n	<li><strong>INFORMASI LAYANAN PUBLIK</strong>: Untuk mengetahui informasi terkait informasi di PPID Utama.</li>\r\n	<li><strong>INFO WISATA</strong>: Untuk mengetahui informasi terkait Wisata di Kota Pangkalpinang.</li>\r\n	<li><strong>INFO VAKSIN COVID</strong>: Untuk mengetahui informasi jumlah penerima vaksinasi Covid-19 di Kota Pangkalpinang.</li>\r\n</ol>\r\n\r\n<p><strong>Terima Kasih.</strong></p>\r\n', NULL, NULL, 30, '2023-09-13 06:41:52', NULL),
(78, '2e346fb5-af41-4a0b-9e30-e398238c4c24', 'P074', 'LAMPU JALAN', '', 'Berikut Informasi Lampu JalanÂ \r\n', NULL, NULL, 24, NULL, NULL),
(84, '980cedf5-2072-4e92-acf5-dbae1bbf39ef', 'P076', 'INFO PPDB', 'INFO PPDB', '<h4 style=\"text-align:justify\">PENDAFTARAN PPDB ONLINE</h4>\r\n\r\n<ol>\r\n	<li style=\"text-align: justify;\"><strong>INFORMASI</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>PENDAFTARAN</strong></li>\r\n	<li style=\"text-align: justify;\"><strong>PERSYARATAN</strong></li>\r\n</ol>\r\n', NULL, NULL, 23, '2023-09-11 03:34:16', NULL),
(85, '50326489-6ac1-4678-9170-b0163db6dbf5', 'P078', 'INFORMASI', 'INFORMASI', '<p><strong>INFORMASI</strong></p>\r\n<ol>\r\n    <li><strong>JENJANG SD</strong></li>\r\n    <li><strong>JENJANG SMP</strong></li>\r\n</ol>\r\n', NULL, NULL, 23, '2023-09-11 03:38:10', NULL),
(86, 'e4cbb8ab-f233-4dc2-aa60-3cac9aec5d44', 'P079', 'JENJANG SD', 'JENJANG SD', '<p><strong>Jenjang SD</strong></p>\r\n\r\n<ul>\r\n	<li>Pendaftaran -- Tanggal 2 s.d. 10 Juni 2021</li>\r\n	<li>Verifikasi -- Tanggal 11 s.d 14 Juni 2021</li>\r\n	<li>Pengumuman -- 26 Juni 2021</li>\r\n	<li>Pendaftaran Ulang -- 28 s.d 30 Juni 2021</li>\r\n	<li>Awal Tahun Ajaran Baru -- 12 Juli 2021</li>\r\n	<li>Pengenalan Lingkungan Sekolah -- 12 s.d 14 Juli 2021</li>\r\n</ul>\r\n', NULL, NULL, 23, '2023-09-13 06:37:25', NULL),
(87, 'b1050c42-9697-4829-a41d-b224b1f27c11', 'P080', 'JENJANG SMP', 'JENJANG SMP', '<p><strong>Jenjang SMP</strong></p>\r\n\r\n<ul>\r\n	<li>Pendaftaran -- Tanggal 15 s.d. 19 Juni 2021</li>\r\n	<li>Verifikasi -- Tanggal 21 s.d 25 Juni 2021</li>\r\n	<li>Pengumuman -- 26 Juni 2021</li>\r\n	<li>Pendaftaran Ulang -- 28 s.d 30 Juni 2021</li>\r\n	<li>Awal Tahun Ajaran Baru -- 12 Juli 2021</li>\r\n	<li>Pengenalan Lingkungan Sekolah -- 12 s.d 14 Juli 2021</li>\r\n</ul>\r\n', NULL, NULL, 23, '2023-09-13 06:38:03', NULL),
(88, '94dae357-832e-478b-95dc-63592621821d', 'P081', 'PERSYARATAN', '', 'Persyaratan Jenjang Calon Peserta Didik :\r\n1. *SD*\r\n2. *SMP*', NULL, NULL, 23, NULL, NULL),
(89, 'ad9568f6-2973-4248-948a-3647b95f51c6', 'P082', 'SD', 'SD', '<p><strong>Persyaratan Calon Peserta Didik SD:</strong></p>\r\n\r\n<ol>\r\n	<li>Berusia minimal <em>6 Tahun terhitung 1 Juli 2021</em>;</li>\r\n	<li>Akte Kelahiran asli;</li>\r\n	<li>Kartu Keluarga asli;</li>\r\n	<li>Pas Photo 3 x 4;</li>\r\n	<li>Kartu Indonesia Pintar (KIP), Kartu Program Keluarga Harapan (PKH), bagi jalur <em>AFIRMASI</em>;</li>\r\n	<li>Surat keterangan mutasi orang tua bagi jalur <em>MUTASI</em>;</li>\r\n</ol>\r\n', NULL, NULL, 23, '2023-09-13 06:41:10', NULL),
(90, 'd9c24b1d-6089-4eb6-8ab6-d3caa8070ad0', 'P083', 'SMP', 'SMP', '<p><strong>Persyaratan Calon Peserta Didik SMP</strong></p>\r\n\r\n<ol>\r\n	<li>Berusia Maksimal <em>15 Tahun terhitung 1 Juli 2021</em>;</li>\r\n	<li>Akte Kelahiran asli;</li>\r\n	<li>Kartu Keluarga asli;</li>\r\n	<li>Ijazah atau Surat Keterangan Lulus asli;</li>\r\n	<li>Pas Photo 3 x 4;</li>\r\n	<li>Kartu Indonesia Pintar (KIP), Kartu Program Keluarga Harapan (PKH) bagi jalur <em>AFIRMASI</em>;</li>\r\n	<li>Sertifikat atau piagam penghargaan tingkat Nasional atau Propinsi bagi jalur <em>PRESTASI</em>;</li>\r\n	<li>Surat keterangan mutasi orang tua bagi jalur <em>MUTASI</em>.</li>\r\n</ol>\r\n', NULL, NULL, 23, '2023-09-13 06:42:58', NULL),
(91, '20ac8dfa-b46b-4f80-ace0-8b3c52fbe835', 'P084', 'PENDAFTARAN', 'PENDAFTARAN', '<p><strong>ALUR PENDAFTARAN</strong></p>\r\n<ol>\r\n    <li>Calon Siswa mengakses laman pendaftaran: <a href=\"https://ppdb.pangkalpinangkota.go.id\">https://ppdb.pangkalpinangkota.go.id</a></li>\r\n    <li>Calon Siswa memilih Zonasi/Prestasi/Afirmasi/Mutasi Sekolah sesuai dengan KK dan melakukan registrasi menggunakan NIK <em>(pastikan untuk KK yang terbaru terutama wilayah pemekaran)</em>;</li>\r\n    <li>Setelah registrasi berhasil, Calon Siswa <em>Login dengan NIK dan Password</em> yang telah dibuat;</li>\r\n    <li>Calon Siswa melakukan pengajuan pendaftaran mandiri dengan mengisi <em>formulir</em> secara daring;</li>\r\n    <li>Calon Siswa melakukan <em>Pemilihan Sekolah</em> sesuai jalur PPDB dan memilih sekolah <em>Swasta</em> untuk pilihan kedua <em>(Khusus SMP)</em>;</li>\r\n    <li>Calon Siswa mengunggah dokumen persyaratan sesuai jalur PPDB dalam <em>bentuk/format photo (JPEG)</em>;</li>\r\n    <li>Calon Siswa <em>mencetak bukti</em> pengajuan pendaftaran;</li>\r\n    <li>Petugas PPDB melakukan <em>verifikasi</em> pendaftaran secara daring;</li>\r\n    <li>Calon Siswa dapat melihat <em>hasil seleksi di menu Proses Seleksi</em> secara daring di laman PPDB;</li>\r\n    <li>Bagi calon Siswa yang diterima, wajib <em>daftar ulang</em> dengan membawa berkas persyaratan <em>yang asli</em>;</li>\r\n    <li>Jika calon siswa berada <em>di luar kuota penerimaan</em>, bisa melakukan edit data untuk <em>memilih Sekolah</em> lain dalam satu zonasi, dan mencetak ulang bukti pendaftaran.</li>\r\n</ol>\r\n', NULL, NULL, 23, '2023-09-13 06:39:17', NULL),
(97, '7fb37eca-8b63-4633-9959-bc7900d5259d', 'P087', 'INFO COVID', 'INFO COVID', '<p style=\"text-align:justify\">Sepradik semua, tetap waspada ya, selalu <strong>#ingatpesanibu</strong>. Pakai masker dan ganti masker setelah 4 jam, cuci tangan dengan sabun, serta jaga jarak. Hindari keramaian dan kurangi aktivitas di luar rumah jika tidak perlu.</p>\r\n\r\n<p style=\"text-align:justify\">Selain itu, agar AMAN terhindar dari Covid-19, tetap disiplin jalankan protokol kesehatan, tingkatkan IMAN dengan beribadah sesuai kepercayaan, dan selalu berdoa kepada Tuhan Yang Maha Esa. Tetap jaga IMUN dengan pola hidup sehat, makan makanan yang sehat, olahraga, dan istirahat yang cukup, serta selalu berpikir positif ya.</p>\r\n\r\n<p style=\"text-align:justify\">Sepradik semua, mari kita tidak mengucilkan orang yang terpapar Covid-19. Tetap berikan semangat dan berdoa agar mereka segera sembuh.</p>\r\n', NULL, NULL, 20, '2023-09-11 03:19:29', NULL),
(99, 'a8a6eb63-7ba0-4283-82ec-1d91a7895a98', 'P088', 'Salam', '', 'Salam juga', NULL, NULL, 30, NULL, NULL),
(100, 'f5e1f5b4-6c82-426e-b1ff-feba387d73a1', 'P089', 'LAPOR', '', 'Silahkan LAPOR pengaduan Anda melalaui : \r\nhttps://pangkalpinang.lapor.go.id\r\n\r\n_Terima kasih_', NULL, NULL, 30, NULL, NULL),
(101, 'ac5df521-2061-428c-8c3e-0e63935ff352', 'P090', 'INFO WISATA', 'INFO WISATA', '<p style=\"text-align:justify\">Untuk Informasi Wisata di Kota Pangkalpinang, silakan mengakses: <a href=\"https://wonderful.pangkalpinangkota.go.id\" target=\"_blank\">https://wonderful.pangkalpinangkota.go.id</a></p>\r\n\r\n<p style=\"text-align:justify\">Terima kasih.</p>\r\n', NULL, NULL, 31, '2023-09-11 03:37:41', NULL),
(102, '3510c963-c427-49a3-82cf-d10c33c03752', 'P091', 'INFO KTP', 'INFO KTP', '<h4>A. Penerbitan KTP-el Baru untuk WNI</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>Sudah melakukan perekaman KTP-el</li>\r\n  <li>Telah berusia 17 (tujuh belas) tahun, sudah kawin atau pernah kawin</li>\r\n  <li>Foto copy Kartu Keluarga (KK)</li>\r\n</ul>\r\n\r\n<h4>B. Penerbitan KTP-el Baru untuk penduduk Orang Asing</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>Sudah melakukan perekaman KTP-el</li>\r\n  <li>Telah berusia 17 (tujuh belas) tahun, sudah kawin atau pernah kawin</li>\r\n  <li>Foto copy Kartu Keluarga (KK)</li>\r\n  <li>Dokumen perjalanan</li>\r\n  <li>Kartu izin tinggal tetap</li>\r\n</ul>\r\n\r\n<h4>C. Penerbitan KTP-el Karena Pindah Datang</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>KTP-el daerah asal atau KTP-el lama</li>\r\n  <li>Foto copy Kartu Keluarga (KK) baru</li>\r\n</ul>\r\n\r\n<h4>D. Penerbitan KTP-el karena hilang</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>Surat keterangan hilang dari kepolisian</li>\r\n  <li>Foto copy KTP-el yang hilang (bila ada)</li>\r\n  <li>Foto copy Kartu Keluarga (KK)</li>\r\n</ul>\r\n\r\n<h4>E. Penerbitan KTP-el karena rusak</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>KTP-el rusak</li>\r\n  <li>Kartu Keluarga (KK)</li>\r\n</ul>\r\n\r\n<h4>F. Penerbitan KTP-el Karena Perpanjangan ITAB (WNA)</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>KTP-el lama</li>\r\n  <li>Dokumen perjalanan</li>\r\n  <li>Kartu Keluarga (KK)</li>\r\n  <li>Kartu izin tinggal tetap</li>\r\n</ul>\r\n\r\n<h4>G. Penerbitan KTP-el Luar Domisili</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>Tidak melakukan perubahan data penduduk</li>\r\n  <li>Foto copy Kartu Keluarga (KK)</li>\r\n</ul>\r\n\r\n<h4>H. Penerbitan KTP-el karena perubahan data untuk WNI</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>Foto copy Kartu Keluarga (KK) yang sudah diperbarui</li>\r\n  <li>KTP-el Lama</li>\r\n</ul>\r\n\r\n<h4>I. Penerbitan KTP-el karena perubahan data untuk penduduk Orang Asing</h4>\r\n<ul>\r\n  <li>Pengisian formulir F1.02</li>\r\n  <li>Kartu Keluarga (KK) yang sudah diperbarui</li>\r\n  <li>KTP-el Lama</li>\r\n  <li>Kartu izin tinggal tetap</li>\r\n</ul>\r\n', NULL, NULL, 34, '2023-09-11 03:26:43', NULL),
(103, 'aa309b63-cfb8-4498-bf5b-866b542b1076', 'P092', 'INFO KK', 'INFO KK', '<h4 style=\"text-align:justify\">A. Penerbitan Kartu Keluarga (KK) Baru untuk WNI</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align: justify;\">Foto copy Buku nikah/kutipan akta perkawinan atau kutipan akta perceraian</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan pindah/surat keterangan pindah datang bagi penduduk yang pindah dalam wilayah NKRI</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan pindah luar negeri yang diterbitkan oleh Disdukcapil Kabupaten/Kota bagi WNI yang datang dari luar wilayah NKRI karena pindah</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan pengganti tanda identitas bagi penduduk rentan Administrasi kependudukan</li>\r\n	<li style=\"text-align: justify;\">Petikan Keputusan Presiden tentang pewarganegaraan dan berita acara pengucapan sumpah atau pernyataan janji setia bagi penduduk WNI yang semula berkewarganegaraan asing atau petikan Keputusan Menteri yang menyelenggarakan urusan pemerintahan dibidang hukum tentang perubahan status kewarganegaraan</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">B. Penerbitan Kartu Keluarga (KK) Baru untuk penduduk Orang Asing</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align: justify;\">Izin tinggal tetap dan dokumen perjalanan</li>\r\n	<li style=\"text-align: justify;\">Buku nikah/kutipan akta perkawinan atau kutipan akta perceraian</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan pindah/surat keterangan pindah datang bagi penduduk yang pindah dalam wilayah NKRI</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">C. Penerbitan Kartu Keluarga (KK) Karena Perubahan Data</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.06 (surat pernyataan perubahan elemen data kependudukan)</li>\r\n	<li style=\"text-align: justify;\">Foto Copy KTP-el</li>\r\n	<li style=\"text-align: justify;\">Kartu Keluarga (KK) Lama</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan /bukti perubahan Peristiwa Kependudukan dan Peristiwa Penting</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">D. Penerbitan Kartu Keluarga (KK) karena hilang atau rusak untuk WNI</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan hilang dari kepolisian atau KK yang rusak</li>\r\n	<li style=\"text-align: justify;\">Foto copy KTP-el</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">E. Penerbitan Kartu Keluarga (KK) karena hilang atau rusak untuk penduduk Orang Asing</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align: justify;\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align: justify;\">Surat keterangan hilang dari kepolisian atau KK yang rusak</li>\r\n	<li style=\"text-align: justify;\">Kartu Izin tinggal</li>\r\n</ul>\r\n', NULL, NULL, 34, '2023-09-11 03:24:34', NULL),
(104, 'c1622e25-9969-4b34-95dd-2ec86c47594d', 'P093', 'INFO KIA', 'INFO KIA', '<h4 style=\"text-align:justify\">A. Penerbitan KIA Baru untuk WNI</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align:justify\">Foto copy kutipan akta kelahiran</li>\r\n	<li style=\"text-align:justify\">Foto copy KTP-el kedua orang tua/wali</li>\r\n	<li style=\"text-align:justify\">Foto copy Kartu Keluarga (KK)</li>\r\n	<li style=\"text-align:justify\">Pas photo anak berwarna ukuran 2x3 sebanyak 2 lembar (untuk anak usia 5 tahun sampai usia 17 tahun kurang 1 hari)</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">B. Penerbitan KIA Baru untuk penduduk Orang Asing</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align:justify\">Foto copy kutipan akta kelahiran</li>\r\n	<li style=\"text-align:justify\">KTP-el kedua orang tua/wali</li>\r\n	<li style=\"text-align:justify\">Foto copy Kartu Keluarga (KK)</li>\r\n	<li style=\"text-align:justify\">Foto copy paspor dan izin tinggal tetap</li>\r\n	<li style=\"text-align:justify\">Pas photo anak berwarna ukuran 2x3 sebanyak 2 lembar (untuk anak usia 5 tahun sampai usia 17 tahun kurang 1 hari)</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">C. Penerbitan KIA karena hilang/rusak untuk WNI</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align:justify\">Foto copy kutipan akta kelahiran</li>\r\n	<li style=\"text-align:justify\">Foto copy KTP-el kedua orang tua/wali</li>\r\n	<li style=\"text-align:justify\">Foto copy Kartu Keluarga (KK)</li>\r\n	<li style=\"text-align:justify\">Surat kehilangan dari kepolisian (untuk KIA yang hilang)</li>\r\n	<li style=\"text-align:justify\">KIA rusak (untuk KIA yang rusak)</li>\r\n	<li style=\"text-align:justify\">Pas photo anak berwarna ukuran 2x3 sebanyak 2 lembar (untuk anak usia 5 tahun sampai usia 17 tahun kurang 1 hari)</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">D. Penerbitan KIA karena hilang/rusak untuk penduduk Orang Asing</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align:justify\">Foto copy kutipan akta kelahiran</li>\r\n	<li style=\"text-align:justify\">KTP-el kedua orang tua/wali</li>\r\n	<li style=\"text-align:justify\">Foto copy Kartu Keluarga (KK)</li>\r\n	<li style=\"text-align:justify\">Foto copy paspor dan izin tinggal tetap</li>\r\n	<li style=\"text-align:justify\">Surat kehilangan dari kepolisian (untuk KIA yang hilang)</li>\r\n	<li style=\"text-align:justify\">KIA rusak (untuk KIA yang rusak)</li>\r\n	<li style=\"text-align:justify\">Pas photo anak berwarna ukuran 2x3 sebanyak 2 lembar (untuk anak usia 5 tahun sampai usia 17 tahun kurang 1 hari)</li>\r\n</ul>\r\n\r\n<h4 style=\"text-align:justify\">E. Penerbitan Kartu Identitas Anak (KIA) Karena Perpanjangan ITAP (WNA)</h4>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">Pengisian formulir F1.02</li>\r\n	<li style=\"text-align:justify\">Foto copy kutipan akta kelahiran</li>\r\n	<li style=\"text-align:justify\">KTP-el kedua orang tua/wali</li>\r\n	<li style=\"text-align:justify\">Foto copy Kartu Keluarga (KK) yang sudah diperbarui</li>\r\n	<li style=\"text-align:justify\">Foto copy paspor dan izin tinggal tetap</li>\r\n	<li style=\"text-align:justify\">KIA Lama</li>\r\n	<li style=\"text-align:justify\">Pas photo anak berwarna ukuran 2x3 sebanyak 2 lembar (untuk anak usia 5 tahun sampai 17 tahun)</li>\r\n</ul>\r\n', NULL, NULL, 34, '2023-09-11 03:22:43', NULL),
(105, '92dcfc76-fcf5-4f99-bdb5-f3e7428e7696', 'P094', 'TDP', 'TDP', '<p><strong>TDP (Tanda Daftar Perusahaan)</strong></p>\r\n\r\n<p><strong>Persyaratan Administrasi:</strong></p>\r\n\r\n<ol>\r\n	<li>Fotocopi Akta Notaris Pendirian Perusahaan</li>\r\n	<li>Fotocopi Akta Perubahan Perusahaan (apabila ada)</li>\r\n	<li>Fotocopi Surat Keputusan Pengesahaan Badan Hukum Perseroan Terbatas dari Departemen Hukum dan Hak Asasi Manusia</li>\r\n	<li>Fotocopi Kartu Tanda Penduduk (KTP) Penanggungjawab Perusahaan</li>\r\n	<li>Fotocopi Surat Izin Usaha Perdagangan (SIUP) dan/atau Surat Izin Teknis lainnya dari instansi yang berwenang</li>\r\n	<li>Fotocopi Surat Izin Gangguan (SIG)/HO</li>\r\n	<li>Fotocopi NPWP perusahaan dan pemohon</li>\r\n	<li>Pas Photo ukuran 3x4 cm sebanyak 4 (empat) lembar</li>\r\n	<li>Surat Kuasa (bila pengurusan perizinan diwakilkan)</li>\r\n</ol>\r\n\r\n<p><em>Terima Kasih.</em></p>\r\n', NULL, NULL, 30, '2023-09-13 06:50:20', NULL);
